    let ret = data["ret"].as_i64();
    let code = data["errcode"].as_i64();
    if ret.is_some_and(|code| code != 0) || code.is_some_and(|code| code != 0) {
        if stale_context(data) {
            bail!("微信会话尚未就绪或已失效，请先向 Bot 发一条消息；仍失败时重新扫码绑定");
        }
        bail!(
            "微信接口错误（ret={}，errcode={}）",
            ret.unwrap_or(0),
            code.unwrap_or(0)
        );
    }
    Ok(())
}

