    let path = f.client.inner.path.as_ref().unwrap();
    assert!(path.exists());
    f.client.retire();
    assert!(!path.exists());
    assert!(f.client.send(&message(), "after-remove").await.is_err());
    assert_eq!(f.mock.sent.lock().unwrap().len(), 1);
