    parent: String,
    name: String,
    kind: FsEntryKind,
}

#[derive(Debug, Clone, Copy, Deserialize)]
#[serde(rename_all = "snake_case")]
enum FsEntryKind {
    File,
    Directory,
}

#[derive(Debug, Deserialize)]
struct RenameFsEntryRequest {
    path: String,
    name: String,
}

#[derive(Debug, Deserialize)]
struct FsEntryPathQuery {
