            state.clone(),
            auth::require_auth,
        ))
        .layer(CompressionLayer::new())
        .layer(TraceLayer::new_for_http())
        .with_state(state);
    Router::new()
        .fallback_service(app)
        .layer(axum::middleware::from_fn_with_state(
            base_path,
            base_path::mount,
        ))
