        .get("ui")
        .filter(|mode| matches!(mode.as_str(), "desktop" | "mobile"))
        .map_or_else(|| "/aow/".to_owned(), |mode| format!("/aow/?ui={mode}"));
    (StatusCode::PERMANENT_REDIRECT, [(LOCATION, location)])
}

async fn aow_root_redirect(
