            .unwrap();
        assert_eq!(directory.status(), StatusCode::CREATED);

        let file = app
            .clone()
            .oneshot(
                Request::post("/api/fs/entries")
                    .header(CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "parent": notes.join("tasks"),
