    }
    if detail.run.status == RunStatus::Failed
        && detail.configuration.failure_notification == Some(FailureNotification::Feishu)
    {
        return Ok(Some(detail.run));
    }
    save(&path, DeliveryStatus::NotRequested, None, None)?;
    Ok(None)
}

