                    !manager
                        .lock()
                        .unwrap()
                        .projects
                        .iter()
                        .find(|p| p.id == project.id)
                        .unwrap()
                        .worktree_icons
                        .contains_key(worktree_path.to_str().unwrap())
                );
            }
        }
