        )
        .await
        .unwrap();
        let mut state = AppState::new(PathBuf::new());
        state.aow = AowManager::persistent(&directory.path().join("state")).unwrap();
        let project = state
            .aow
            .register_project(RegisterProjectRequest {
                path: repository.to_string_lossy().into_owned(),
