        std::fs::write(Path::new(&paths[0]).join("uncommitted.txt"), "keep me").unwrap();
        git_output(&repository, &["worktree", "lock", &paths[2]])
            .await
            .unwrap();
        (directory, state, project, paths)
    }

    async fn wait_finished(state: &AppState, id: &str) -> RemovalJob {
        tokio::time::timeout(std::time::Duration::from_secs(15), async {
            loop {
                let job = state
                    .aow
                    .inner
                    .removals
                    .lock()
                    .unwrap()
                    .iter()
                    .find(|job| job.id == id)
                    .unwrap()
                    .clone();
                if job.items.iter().all(|item| !item.status.active()) {
                    return job;
                }
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap()
    }

    #[tokio::test]
    async fn request_returns_accepted_while_worker_waits_and_rejects_duplicate_deletion() {
        let (_directory, state, project, paths) = fixture().await;
        let manager = state.aow.clone();
        let permit = manager
            .inner
            .removals
            .permits
            .acquire_many(2)
            .await
            .unwrap();
        let router = crate::build_router(state.clone());
        let request = || {
            Request::builder()
                .method("POST")
                .uri(format!(
                    "/api/aow/projects/{}/worktrees/removals",
                    project.id
                ))
                .header("content-type", "application/json")
                .body(Body::from(
                    serde_json::json!({"items": [{"path": paths[1]}]}).to_string(),
                ))
                .unwrap()
        };
        let response = tokio::time::timeout(
            std::time::Duration::from_secs(2),
            router.clone().oneshot(request()),
        )
        .await
        .unwrap()
        .unwrap();
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        let job: RemovalJob =
            serde_json::from_slice(&to_bytes(response.into_body(), 100_000).await.unwrap())
                .unwrap();
        assert_eq!(job.items[0].status, RemovalStatus::Queued);
        assert!(Path::new(&paths[1]).exists());
        assert_eq!(
            router.clone().oneshot(request()).await.unwrap().status(),
            StatusCode::CONFLICT
        );
        assert!(matches!(
            state.aow.remove_project(&project.id).await,
            Err(AowError::RemovalConflict(_))
        ));
        let response = router
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/api/terminals")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({"workspace_root": paths[1], "cwd": paths[1]})
                            .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(!response.status().is_success());
        let error = String::from_utf8(
            to_bytes(response.into_body(), 100_000)
                .await
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        assert!(error.contains("Worktree 正在清理"), "{error}");
        drop(permit);
        assert_eq!(
            wait_finished(&state, &job.id).await.items[0].status,
            RemovalStatus::Succeeded
        );
        assert!(!Path::new(&paths[1]).exists());
    }

    #[tokio::test]
    async fn batch_isolates_failures_protects_main_locked_and_dirty_and_supports_explicit_retry() {
        let (directory, state, project, paths) = fixture().await;
        let outside = directory.path().join("outside");
        std::fs::create_dir(&outside).unwrap();
        let job = submit(
            state.clone(),
            project.id.clone(),
            [
                paths[0].clone(),
                paths[1].clone(),
                paths[2].clone(),
                project.registered_path.clone(),
                outside.to_string_lossy().into_owned(),
            ]
            .into_iter()
            .map(|path| RemovalRequest { path, force: false })
            .collect(),
        )
        .unwrap();
        let completed = wait_finished(&state, &job.id).await;
        assert_eq!(
            completed
                .items
                .iter()
                .map(|item| item.status)
                .collect::<Vec<_>>(),
            vec![
                RemovalStatus::Failed,
                RemovalStatus::Succeeded,
                RemovalStatus::Failed,
                RemovalStatus::Failed,
                RemovalStatus::Failed
            ]
        );
        assert!(Path::new(&paths[0]).join("uncommitted.txt").exists());
        assert!(!Path::new(&paths[1]).exists());
        assert!(Path::new(&paths[2]).exists());
        assert!(Path::new(&project.registered_path).exists());
        assert!(outside.exists());
        let retry = submit(
            state.clone(),
            project.id.clone(),
            vec![RemovalRequest {
                path: paths[0].clone(),
                force: true,
            }],
        )
        .unwrap();
        assert_eq!(
            wait_finished(&state, &retry.id).await.items[0].status,
            RemovalStatus::Succeeded
        );
        assert!(!Path::new(&paths[0]).exists());
        let branches = git_output(
            Path::new(&project.registered_path),
            &["branch", "--format=%(refname:short)"],
        )
        .await
        .unwrap();
        assert!(branches.lines().any(|branch| branch == "dirty"));
        assert!(branches.lines().any(|branch| branch == "clean"));
        let restored = AowManager::persistent(&directory.path().join("state")).unwrap();
        assert!(restored.inner.removals.lock().unwrap().is_empty());
        assert!(
            !directory
                .path()
                .join("state/worktree-removals.json")
                .exists()
        );
    }

    #[test]
    fn legacy_history_is_ignored_even_when_invalid() {
        let directory = tempfile::tempdir().unwrap();
        std::fs::write(directory.path().join("worktree-removals.json"), "not json").unwrap();
        let restored = AowManager::persistent(directory.path()).unwrap();
        assert!(restored.inner.removals.lock().unwrap().is_empty());
    }
}

use std::{
    collections::HashMap,
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
};

use axum::{
    Json,
    extract::{Request, State},
    http::{
        HeaderMap, HeaderValue, StatusCode,
        header::{COOKIE, SET_COOKIE},
    },
    middleware::Next,
    response::{IntoResponse, Response},
};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{AppState, HttpError};

pub(crate) const PIN_HASH_FILE: &str = "pin.md5";
const SESSION_COOKIE: &str = "aow_session";

#[derive(Clone)]
pub(crate) struct PinAuth {
    cookie_name: String,
    pin_hash_path: Option<PathBuf>,
    sessions: Arc<Mutex<HashMap<String, String>>>,
}

enum PinConfiguration {
    Disabled,
    NotConfigured,
    Configured(String),
    Invalid(String),
}

#[derive(Serialize)]
pub(crate) struct AuthStatus {
    pub configured: bool,
    pub authenticated: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
}

#[derive(Deserialize)]
pub(crate) struct LoginRequest {
    pub pin: String,
}

impl PinAuth {
    pub(crate) fn persistent(state_dir: &Path) -> Self {
        Self {
            cookie_name: SESSION_COOKIE.to_owned(),
            pin_hash_path: Some(state_dir.join(PIN_HASH_FILE)),
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// In-memory application states are used by embedders and the existing
    /// route test suite. The server binary always uses `persistent`.
    pub(crate) fn disabled() -> Self {
        Self {
            cookie_name: SESSION_COOKIE.to_owned(),
            pin_hash_path: None,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub(crate) fn set_cookie_name(&mut self, name: String) {
        self.cookie_name = name;
    }

    pub(crate) fn status(&self, headers: &HeaderMap) -> AuthStatus {
        match self.configuration() {
            PinConfiguration::Configured(hash) => AuthStatus {
                configured: true,
                authenticated: self.has_session(headers, &hash),
                message: None,
            },
            PinConfiguration::Disabled => AuthStatus {
                configured: false,
                authenticated: false,
                message: None,
            },
            PinConfiguration::NotConfigured => AuthStatus {
                configured: false,
                authenticated: false,
                message: Some(format!(
                    "尚未配置 PIN。请在服务器上运行 `aow pin`，它会创建 {PIN_HASH_FILE}。"
                )),
            },
            PinConfiguration::Invalid(message) => AuthStatus {
                configured: false,
                authenticated: false,
                message: Some(message),
            },
        }
    }

    pub(crate) fn authorize(&self, headers: &HeaderMap) -> Result<(), HttpError> {
        match self.configuration() {
            PinConfiguration::Disabled => Ok(()),
            PinConfiguration::Configured(hash) if self.has_session(headers, &hash) => Ok(()),
            PinConfiguration::Configured(_) => Err(authentication_required()),
            PinConfiguration::NotConfigured => Err(pin_not_configured()),
            PinConfiguration::Invalid(message) => Err(HttpError::new(
                StatusCode::SERVICE_UNAVAILABLE,
                "pin_configuration_invalid",
                message,
                None,
            )),
        }
    }

    pub(crate) fn login(&self, pin: &str) -> Result<String, HttpError> {
        if !valid_pin(pin) {
            return Err(HttpError::new(
                StatusCode::BAD_REQUEST,
                "invalid_pin",
                "PIN 必须恰好为 6 位数字",
                None,
            ));
        }
        let expected_hash = match self.configuration() {
            PinConfiguration::Configured(hash) => hash,
            PinConfiguration::Disabled | PinConfiguration::NotConfigured => {
                return Err(pin_not_configured());
            }
            PinConfiguration::Invalid(message) => {
                return Err(HttpError::new(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "pin_configuration_invalid",
                    message,
                    None,
                ));
            }
        };
        let entered_hash = format!("{:x}", md5::compute(pin.as_bytes()));
        if !constant_time_eq(&entered_hash, &expected_hash) {
            return Err(HttpError::new(
                StatusCode::UNAUTHORIZED,
                "invalid_pin",
                "PIN 不正确",
                None,
            ));
        }

        let token = Uuid::new_v4().simple().to_string();
        self.sessions
            .lock()
            .map_err(|_| HttpError::internal("PIN 会话锁不可用"))?
            .insert(token.clone(), expected_hash);
        Ok(token)
    }

    fn has_session(&self, headers: &HeaderMap, current_hash: &str) -> bool {
        let Some(token) = session_token(headers, &self.cookie_name) else {
            return false;
        };
        let Ok(mut sessions) = self.sessions.lock() else {
            return false;
        };
        let Some(session_hash) = sessions.get(token) else {
            return false;
        };
        if constant_time_eq(session_hash, current_hash) {
            true
        } else {
            // A newly configured PIN invalidates sessions created with the old one.
            sessions.remove(token);
            false
        }
    }

    fn configuration(&self) -> PinConfiguration {
        let Some(path) = &self.pin_hash_path else {
            return PinConfiguration::Disabled;
        };
        let contents = match std::fs::read_to_string(path) {
            Ok(contents) => contents,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return PinConfiguration::NotConfigured;
            }
            Err(error) => {
                return PinConfiguration::Invalid(format!(
                    "无法读取 PIN 配置 {}：{error}",
                    path.display()
                ));
            }
        };
        let hash = contents.trim();
        if hash.len() != 32 || !hash.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return PinConfiguration::Invalid(format!(
                "PIN 配置 {} 无效；请重新运行 `aow pin`",
                path.display()
            ));
        }
        PinConfiguration::Configured(hash.to_ascii_lowercase())
    }
}

pub(crate) async fn status(State(state): State<AppState>, headers: HeaderMap) -> Json<AuthStatus> {
    Json(state.auth.status(&headers))
}

pub(crate) async fn login(
    State(state): State<AppState>,
    Json(request): Json<LoginRequest>,
) -> Result<Response, HttpError> {
    let token = state.auth.login(&request.pin)?;
    let mut response = Json(AuthStatus {
        configured: true,
        authenticated: true,
        message: None,
    })
    .into_response();
    response.headers_mut().insert(
        SET_COOKIE,
        HeaderValue::from_str(&format!(
            "{}={token}; Path={}; HttpOnly; SameSite=Strict",
            state.auth.cookie_name,
            state.base_path.url("/")
        ))
        .expect("UUID session token is a valid cookie value"),
    );
    Ok(response)
}

pub(crate) async fn require_auth(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    // Only the registered read-only share route bypasses PIN authentication.
    // A share token never establishes a AOW login session.
    let public_share = matches!(
        *request.method(),
        axum::http::Method::GET | axum::http::Method::HEAD
    ) && request
        .extensions()
        .get::<axum::extract::MatchedPath>()
        .is_some_and(|path| path.as_str() == crate::session_shares::PUBLIC_API_PATH);
    let protected = (path.starts_with("/api/")
        && !public_share
        && !matches!(path, "/api/health" | "/api/auth/status" | "/api/auth/login"))
        || path == "/fs"
        || path.starts_with("/fs/")
        || path == "/help";
    if protected && let Err(error) = state.auth.authorize(request.headers()) {
        return error.into_response();
    }
    next.run(request).await
}

#[cfg(test)]
pub(crate) fn cookie_header(token: &str) -> HeaderValue {
    HeaderValue::from_str(&format!("{SESSION_COOKIE}={token}"))
        .expect("UUID session token is a valid cookie value")
}

fn session_token<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers
        .get(COOKIE)
        .and_then(|value| value.to_str().ok())
        .and_then(|cookie| {
            cookie
                .split(';')
                .map(str::trim)
                .find_map(|entry| entry.strip_prefix(&format!("{name}=")))
        })
}

fn valid_pin(pin: &str) -> bool {
    pin.len() == 6 && pin.bytes().all(|byte| byte.is_ascii_digit())
}

fn constant_time_eq(left: &str, right: &str) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut difference = 0_u8;
    for (left, right) in left.bytes().zip(right.bytes()) {
        difference |= left ^ right;
    }
    difference == 0
}

fn pin_not_configured() -> HttpError {
    HttpError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "pin_not_configured",
        "AOW 尚未配置 PIN；请在服务器上运行 `aow pin`",
        None,
    )
}

fn authentication_required() -> HttpError {
    HttpError::new(
        StatusCode::UNAUTHORIZED,
        "authentication_required",
        "需要输入 PIN 码后才能访问 AOW",
        None,
    )
}

#[cfg(test)]
mod tests {
    use std::fs;

    use super::*;

    #[test]
    fn validates_only_six_digit_pins() {
        assert!(valid_pin("012345"));
        assert!(!valid_pin("12345"));
        assert!(!valid_pin("1234567"));
        assert!(!valid_pin("12a456"));
    }

    #[test]
    fn changed_pin_invalidates_existing_sessions() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join(PIN_HASH_FILE);
        fs::write(&path, format!("{:x}\n", md5::compute(b"123456"))).unwrap();
        let auth = PinAuth::persistent(directory.path());
        let token = auth.login("123456").unwrap();
        let mut headers = HeaderMap::new();
        headers.insert(COOKIE, cookie_header(&token));
        assert!(auth.authorize(&headers).is_ok());

        fs::write(&path, format!("{:x}\n", md5::compute(b"654321"))).unwrap();
        assert!(auth.authorize(&headers).is_err());
    }
}

use std::{
    collections::BTreeMap,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};

use anyhow::{Context, Result, ensure};
use aow_automations::{
    AgentLaunch, Run, RunOutput, RunSource, Scheduler, Store, Task, TaskInput, TaskKind, TaskView,
    WorkspaceMode, scheduler::SchedulerStatus,
};
use axum::{
    Json, Router,
    extract::{Path, Query, State},
    http::{StatusCode, header},
    response::{IntoResponse, Response},
    routing::{get, post, put},
};
use chrono::Utc;
use serde::Deserialize;

use crate::{AppState, PROCESS_HOME};

mod notifications;

const RUN_HISTORY_RETENTION: usize = 200;
const RUN_HISTORY_CLEANUP_INTERVAL: Duration = Duration::from_secs(5 * 60);
const FAILURE_NOTIFICATION_INTERVAL: Duration = Duration::from_secs(5);

#[derive(Clone)]
pub(crate) struct AutomationManager {
    store: Arc<Store>,
    scheduler: Scheduler,
    operation: Arc<tokio::sync::Mutex<()>>,
}

impl AutomationManager {
    pub(crate) fn new(
        state_dir: PathBuf,
        notifications: crate::notifications::NotificationManager,
    ) -> Result<Self> {
        let manager = Self {
            store: Arc::new(Store::new(state_dir)?),
            scheduler: Scheduler::new(&PROCESS_HOME),
            operation: Arc::new(tokio::sync::Mutex::new(())),
        };
        manager.start_background_tasks(notifications);
        Ok(manager)
    }

    fn start_background_tasks(&self, notifications: crate::notifications::NotificationManager) {
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return;
        };
        let store = Arc::downgrade(&self.store);
        handle.spawn(async move {
            let mut last_cleanup = None;
            let mut interval = tokio::time::interval(FAILURE_NOTIFICATION_INTERVAL);
            interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                interval.tick().await;
                let Some(store) = store.upgrade() else { break };
                let prune = last_cleanup
                    .is_none_or(|last: Instant| last.elapsed() >= RUN_HISTORY_CLEANUP_INTERVAL);
                let result = notifications::poll(
                    store,
                    |run, channel, delivery_id| {
                        let notifications = notifications.clone();
                        async move {
                            notifications
                                .send_automation_failure(run, channel, &delivery_id)
                                .await
                        }
                    },
                    prune,
                )
                .await;
                match result {
                    Ok(()) if prune => last_cleanup = Some(Instant::now()),
                    Ok(()) => {}
                    Err(error) => {
                        tracing::warn!(%error, "failed to check automation failure notifications")
                    }
                }
            }
        });
    }

    async fn save(&self, mut task: Task) -> Result<TaskView> {
        // Persist the desired configuration first. Even an old installed trigger
        // reads the new enabled flag, and a dropped HTTP request leaves a visible error.
        task.scheduler_error = Some("定时器配置待同步".into());
        self.store.save_task(&task)?;
        task.scheduler_error = self
            .scheduler
            .sync(&self.store, &task)
            .await
            .err()
            .map(|e| format!("{e:#}"));
        self.store.save_task(&task)?;
        self.view(task)
    }

    fn view(&self, task: Task) -> Result<TaskView> {
        self.store.task_view(task)
    }

    fn task(&self, id: &str) -> Result<Task> {
        let task = self.store.get_task(id)?;
        ensure!(!task.deleted, "自动化任务已删除");
        Ok(task)
    }

    pub(crate) fn run(&self, task_id: &str, run_id: &str) -> Result<Run> {
        self.store.get_task(task_id)?;
        self.store
            .read_run(task_id, run_id)?
            .context("执行记录尚未生成")
    }
}

fn error(error: impl std::fmt::Display) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(serde_json::json!({ "message": error.to_string() })),
    )
        .into_response()
}

fn manager(state: &AppState) -> Result<&AutomationManager, (StatusCode, Json<serde_json::Value>)> {
    state.automations.as_ref().ok_or_else(|| {
        (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(serde_json::json!({ "message": "自动化需要持久化状态目录" })),
        )
    })
}

pub(crate) fn routes() -> Router<AppState> {
    Router::new()
        .route("/api/aow/automations/status", get(status))
        .route("/api/aow/automations", get(list).post(create))
        .route(
            "/api/aow/automations/{id}",
            get(detail).put(update).delete(remove),
        )
        .route("/api/aow/automations/{id}/enabled", put(set_enabled))
        .route("/api/aow/automations/{id}/sync", post(sync))
        .route("/api/aow/automations/{id}/run", post(run))
        .route("/api/aow/automations/{id}/runs", get(runs))
        .route(
            "/api/aow/automations/{id}/runs/{run_id}/output/{output}",
            get(run_output),
        )
        .route("/api/aow/automations/{id}/runs/{run_id}", get(run_detail))
}

async fn status(State(state): State<AppState>) -> Result<Json<SchedulerStatus>, Response> {
    Ok(Json(
        manager(&state)
            .map_err(IntoResponse::into_response)?
            .scheduler
            .status()
            .await,
    ))
}

#[derive(Deserialize)]
struct ListQuery {
    project_id: Option<String>,
}

async fn list(
    State(state): State<AppState>,
    Query(query): Query<ListQuery>,
) -> Result<Json<Vec<TaskView>>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    Ok(Json(
        manager
            .store
            .tasks()
            .map_err(error)?
            .into_iter()
            .filter(|task| {
                query
                    .project_id
                    .as_deref()
                    .is_none_or(|project_id| task.input.project_id == project_id)
            })
            .map(|task| manager.view(task))
            .collect::<Result<_>>()
            .map_err(error)?,
    ))
}

async fn detail(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<TaskView>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    Ok(Json(
        manager
            .view(manager.task(&id).map_err(error)?)
            .map_err(error)?,
    ))
}

async fn resolve(state: &AppState, input: &TaskInput) -> Result<(String, PathBuf, AgentLaunch)> {
    input.validate()?;
    let (name, repository) = state
        .aow
        .automation_project(&input.project_id, &input.workspace_path)
        .await?;
    let agent_id = input.agent.id();
    let launch = state
        .aow
        .resolve_agent_launch(
            agent_id,
            input
                .workspace_path
                .to_str()
                .context("工作区路径不是 UTF-8")?,
        )
        .await?;
    let environment = aow_agents::automation::configuration_environment();
    let launch = AgentLaunch {
        executable: launch.executable.into(),
        args: launch.args,
        environment,
    };
    aow_automations::agent::validate_arguments(input.agent, &launch.args)?;
    Ok((name, repository, launch))
}

fn force_worktree_cleanup(input: &mut TaskInput) {
    if input.workspace_mode == WorkspaceMode::NewWorktree {
        input.cleanup_worktree = true;
    }
}

async fn create(
    State(state): State<AppState>,
    Json(mut input): Json<TaskInput>,
) -> Result<(StatusCode, Json<TaskView>), Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    force_worktree_cleanup(&mut input);
    let (project_name, repository_path, launch) = resolve(&state, &input).await.map_err(error)?;
    let task = Task {
        id: manager.store.new_task_id().map_err(error)?,
        revision: 1,
        created_at: Utc::now(),
        updated_at: Utc::now(),
        input,
        project_name,
        repository_path,
        launch,
        scheduler_error: None,
        deleted: false,
    };
    manager
        .scheduler
        .render(&manager.store, &task)
        .map_err(error)?;
    Ok((
        StatusCode::CREATED,
        Json(manager.save(task).await.map_err(error)?),
    ))
}

#[derive(Deserialize)]
struct UpdateInput {
    revision: u64,
    #[serde(flatten)]
    input: TaskInput,
}

async fn update(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(mut request): Json<UpdateInput>,
) -> Result<Json<TaskView>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    let mut task = manager.task(&id).map_err(error)?;
    if task.revision != request.revision {
        return Err(error("任务已被修改，请刷新后重试"));
    }
    force_worktree_cleanup(&mut request.input);
    let (project_name, repository_path, launch) =
        resolve(&state, &request.input).await.map_err(error)?;
    task.input = request.input;
    task.project_name = project_name;
    task.repository_path = repository_path;
    task.launch = launch;
    task.revision += 1;
    task.updated_at = Utc::now();
    manager
        .scheduler
        .render(&manager.store, &task)
        .map_err(error)?;
    Ok(Json(manager.save(task).await.map_err(error)?))
}

#[derive(Deserialize)]
struct EnabledInput {
    enabled: bool,
}

async fn set_enabled(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(input): Json<EnabledInput>,
) -> Result<Json<TaskView>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    let mut task = manager.task(&id).map_err(error)?;
    task.input.enabled = input.enabled;
    if task.input.kind == TaskKind::Manual {
        return Err(error("手动任务无需暂停或启用"));
    }
    task.revision += 1;
    task.updated_at = Utc::now();
    Ok(Json(manager.save(task).await.map_err(error)?))
}

async fn sync(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<TaskView>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    Ok(Json(
        manager
            .save(manager.task(&id).map_err(error)?)
            .await
            .map_err(error)?,
    ))
}

async fn remove(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<StatusCode, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    let mut task = manager.task(&id).map_err(error)?;
    task.input.enabled = false;
    task.revision += 1;
    task.updated_at = Utc::now();
    task.scheduler_error = Some("定时器正在移除".into());
    manager.store.save_task(&task).map_err(error)?;
    task.deleted = true;
    if let Err(reason) = manager.scheduler.sync(&manager.store, &task).await {
        task.deleted = false;
        task.scheduler_error = Some(reason.to_string());
        manager.store.save_task(&task).map_err(error)?;
        return Err(error(reason));
    }
    task.scheduler_error = None;
    manager.store.save_task(&task).map_err(error)?;
    // Tombstones and run files are retained; running processes own their journals.
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Default, Deserialize)]
struct ManualRunInput {
    revision: Option<u64>,
    #[serde(default)]
    variables: BTreeMap<String, String>,
}

async fn run(
    State(state): State<AppState>,
    Path(id): Path<String>,
    body: axum::body::Bytes,
) -> Result<(StatusCode, Json<serde_json::Value>), Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    let _operation = manager.operation.lock().await;
    let task = manager.task(&id).map_err(error)?;
    let request: ManualRunInput = if body.is_empty() {
        ManualRunInput::default()
    } else {
        serde_json::from_slice(&body).map_err(error)?
    };
    if (task.input.kind == TaskKind::Manual && request.revision != Some(task.revision))
        || request
            .revision
            .is_some_and(|revision| revision != task.revision)
    {
        return Err(error("任务已被修改，请刷新后重新填写变量"));
    }
    let run_id = manager
        .scheduler
        .dispatch_with_variables(&manager.store, &task, RunSource::Manual, request.variables)
        .await
        .map_err(error)?;
    Ok((
        StatusCode::ACCEPTED,
        Json(serde_json::json!({ "run_id": run_id })),
    ))
}

#[derive(Deserialize)]
struct RunsQuery {
    before: Option<String>,
    limit: Option<usize>,
}

async fn runs(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<RunsQuery>,
) -> Result<Json<Vec<Run>>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    manager.store.get_task(&id).map_err(error)?;
    Ok(Json(
        manager
            .store
            .runs(
                &id,
                query.before.as_deref(),
                query.limit.unwrap_or(50).clamp(1, 500),
            )
            .map_err(error)?,
    ))
}

async fn run_detail(
    State(state): State<AppState>,
    Path((id, run_id)): Path<(String, String)>,
) -> Result<Json<Run>, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    manager.store.get_task(&id).map_err(error)?;
    Ok(Json(
        manager
            .store
            .read_run(&id, &run_id)
            .map_err(error)?
            .ok_or_else(|| error("执行记录尚未生成"))?,
    ))
}

async fn run_output(
    State(state): State<AppState>,
    Path((id, run_id, output)): Path<(String, String, String)>,
) -> Result<Response, Response> {
    let manager = manager(&state).map_err(IntoResponse::into_response)?;
    manager.store.get_task(&id).map_err(error)?;
    let output = match output.as_str() {
        "stdio" => RunOutput::Stdio,
        "stderr" => RunOutput::Stderr,
        _ => return Err(error("输出类型必须是 stdio 或 stderr")),
    };
    let bytes = manager
        .store
        .read_run_output(&id, &run_id, output)
        .map_err(error)?;
    Ok(([(header::CONTENT_TYPE, "text/plain; charset=utf-8")], bytes).into_response())
}

