fn finish(writer: &mut RunWriter, status: RunStatus) {
    writer
        .append(&RunEvent::Finished {
            at: Utc::now(),
            status,
            exit_code: Some(1),
            message: Some("Agent 退出失败".into()),
            duration_ms: 1234,
