            "/index.html",
        ] {
            let response = get(&app, &format!("{base}{path}")).await;
            assert_eq!(response.status(), StatusCode::OK, "{base}{path}");
            let html = body(response).await;
            assert!(html.contains(&format!("<base href=\"{base}/\">")));
            assert!(html.contains(&format!("name=\"aow-base-path\" content=\"{base}\"")));
            assert!(html.contains("./assets/app.js"));
        }
        let response = get(&app, &format!("{base}/assets/app.js")).await;
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(body(response).await, "export const ready = true;");
        let redirect = get(&app, &format!("{base}/?ui=mobile")).await;
        assert_eq!(
            redirect.headers()[LOCATION],
            format!("{base}/aow/?ui=mobile")
        );
        assert_eq!(
            get(&app, &format!("{base}/api/health")).await.status(),
            StatusCode::OK
        );
    }
}

#[tokio::test]
async fn mount_is_bounded_and_preserves_authentication_and_cookie_scope() {
    let (_root, state) = fixture("/tools/aow");
    let root_app = build_router(state.clone().with_base_path(BasePath::default()));
    let app = build_router(state);
    let redirect = get(&app, "/tools/aow?ui=desktop").await;
    assert_eq!(redirect.headers()[LOCATION], "/tools/aow/?ui=desktop");
    for path in [
        "/api/health",
        "/aow/",
        "/assets/app.js",
        "/tools/aow-other/api/health",
    ] {
        assert_eq!(
            get(&app, path).await.status(),
            StatusCode::NOT_FOUND,
            "{path}"
        );
    }
    for path in [
        "/api/fs/tree",
        "/api/operations/stream",
        "/api/terminals/task-stops",
        "/help",
        "/fs/",
    ] {
        assert_eq!(
            get(&app, &format!("/tools/aow{path}")).await.status(),
            StatusCode::UNAUTHORIZED,
            "{path}"
        );
    }
    // The exact public read route still bypasses login; other API routes do not.
    assert_eq!(
        get(&app, "/tools/aow/api/public/session-shares/missing")
            .await
            .status(),
        StatusCode::NOT_FOUND
    );
    assert_eq!(
        get(&app, "/tools/aow/api/public/session-shares/missing/extra")
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    let login = app
        .clone()
        .oneshot(
            Request::post("/tools/aow/api/auth/login")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"pin":"123456"}"#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(login.status(), StatusCode::OK);
    let cookie = login.headers()["set-cookie"].to_str().unwrap();
    assert!(cookie.starts_with("aow_session_"));
    assert!(cookie.contains("Path=/tools/aow/; HttpOnly; SameSite=Strict"));
    let cookie = cookie.split(';').next().unwrap();
    for (router, path, status) in [
        (&app, "/tools/aow/api/fs/tree", StatusCode::OK),
        (&root_app, "/api/fs/tree", StatusCode::UNAUTHORIZED),
    ] {
        let response = router
            .clone()
            .oneshot(
                Request::get(path)
                    .header("cookie", cookie)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), status);
    }
    for (path, expected) in [
        ("/help", "/tools/aow/api/fs/tree"),
        ("/fs/", "/tools/aow/fs/tmp/"),
    ] {
        let response = app
            .clone()
            .oneshot(
                Request::get(format!("/tools/aow{path}"))
                    .header("cookie", cookie)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert!(body(response).await.contains(expected));
    }
}

//! Authenticated HTTP boundary only; all IM protocol/auth/session logic is in aow-im.
use aow_im::{ImConfigUpdate, ImKind, ImProvider, Message};
use axum::{
    Json, Router,
    extract::{Path, State},
    http::{StatusCode, header::CACHE_CONTROL},
    response::{IntoResponse, Response},
    routing::{get, post, put},
};
use serde::Deserialize;
use serde_json::json;

use crate::{AppState, notifications::SettingsUpdate};

pub(crate) fn routes() -> Router<AppState> {
    Router::new()
        .route("/api/aow/im/feishu", put(save_feishu).delete(remove_feishu))
        .route("/api/aow/im/wechat", get(status).delete(disconnect))
        .route("/api/aow/im/wechat/login", post(start_login))
        // POST because confirmation persists credentials; verification codes stay out of URLs.
        .route(
            "/api/aow/im/wechat/login/{id}",
            post(poll_login).delete(cancel_login),
        )
        .route("/api/aow/im/wechat/test", post(test_send))
}

fn error(error: impl std::fmt::Display) -> Response {
    (
        StatusCode::BAD_REQUEST,
        [(CACHE_CONTROL, "no-store")],
        Json(json!({"message":error.to_string()})),
    )
        .into_response()
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct FeishuInput {
    app_id: String,
    app_secret: Option<String>,
}

async fn save_feishu(State(state): State<AppState>, Json(input): Json<FeishuInput>) -> Response {
    update(
        &state,
        SettingsUpdate::ImProvider {
            config: ImConfigUpdate::Feishu {
                app_id: input.app_id,
                app_secret: input.app_secret,
            },
        },
    )
    .await
}

async fn remove_feishu(State(state): State<AppState>) -> Response {
    update(
        &state,
        SettingsUpdate::ImRemove {
            provider: ImKind::Feishu,
        },
    )
    .await
}

async fn update(state: &AppState, input: SettingsUpdate) -> Response {
    let manager = state.aow.notifications().clone();
    match tokio::task::spawn_blocking(move || manager.update(input)).await {
        Ok(Ok(view)) => ([(CACHE_CONTROL, "no-store")], Json(view)).into_response(),
        Ok(Err(reason)) => error(reason),
        Err(_) => error("无法保存 IM 配置"),
    }
}

async fn status(State(state): State<AppState>) -> Response {
    let connection = state
        .aow
        .notifications()
        .wechat()
        .map(|client| client.status());
    (
        [(CACHE_CONTROL, "no-store")],
        Json(json!({"connection":connection})),
    )
        .into_response()
}

async fn start_login(State(state): State<AppState>) -> Response {
    let manager = state.aow.notifications();
    match manager
        .wechat_login()
        .start(manager.wechat_credentials())
        .await
    {
        Ok(view) => ([(CACHE_CONTROL, "no-store")], Json(view)).into_response(),
        Err(reason) => error(reason),
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct PollInput {
    verify_code: Option<String>,
}

async fn poll_login(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(input): Json<PollInput>,
) -> Response {
    let manager = state.aow.notifications();
    match manager
        .wechat_login()
        .poll(&id, input.verify_code.as_deref(), |credentials| {
            // The login manager holds its short commit lock, protecting cancellation
            // and rebind races. This local atomic save occurs only on confirmation.
            manager.update(SettingsUpdate::WechatBinding { credentials })?;
            Ok(())
        })
        .await
    {
        Ok(view) => ([(CACHE_CONTROL, "no-store")], Json(view)).into_response(),
        Err(reason) => error(reason),
    }
}

async fn cancel_login(State(state): State<AppState>, Path(id): Path<String>) -> Response {
    state.aow.notifications().wechat_login().cancel(&id);
    ([(CACHE_CONTROL, "no-store")], StatusCode::NO_CONTENT).into_response()
}

async fn disconnect(State(state): State<AppState>) -> Response {
    state.aow.notifications().wechat_login().cancel_all();
    update(
        &state,
        SettingsUpdate::ImRemove {
            provider: ImKind::Wechat,
        },
    )
    .await
}

async fn test_send(State(state): State<AppState>) -> Response {
    let Some(client) = state.aow.notifications().wechat() else {
        return error("请先扫码绑定微信 Bot");
    };
    let message = Message {
        title: "AoW 微信推送测试".into(),
        fields: vec![],
        body_label: "测试消息".into(),
        body: "微信通知已连通。可在 Settings → 通知中启用微信推送。".into(),
        markdown: false,
        error: false,
    };
    match client
        .send(&message, &uuid::Uuid::new_v4().to_string())
        .await
    {
        Ok(()) => (
            [(CACHE_CONTROL, "no-store")],
            Json(json!({"message":"测试消息已发送。"})),
        )
            .into_response(),
        Err(reason) => error(reason),
    }
}

