    let repo = directory.path().join("repo with spaces");
    std::fs::create_dir(&repo).unwrap();
    for args in [
        vec!["init", "-b", "main"],
        vec![
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.invalid",
            "commit",
            "--allow-empty",
            "-m",
            "initial",
        ],
    ] {
        let output = std::process::Command::new("git")
            .current_dir(&repo)
            .args(args)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
    let app = crate::build_router(state);
    let response = app.clone().oneshot(
        Request::post("/api/aow/projects")
            .header("content-type", "application/json")
            .body(Body::from(json!({"path":repo, "name":"项目", "notes_path":directory.path().join("notes")}).to_string())).unwrap()
    ).await.unwrap();
    let status = response.status();
    let bytes = to_bytes(response.into_body(), 1024 * 1024).await.unwrap();
    assert!(
        status.is_success(),
        "{status}: {}",
        String::from_utf8_lossy(&bytes)
    );
    let project: Value = serde_json::from_slice(&bytes).unwrap();
    let path = format!("/v1/projects/{}", project["id"].as_str().unwrap());
    let expected =
        json!({"id":project["id"], "name":"项目", "repo_path":repo.canonicalize().unwrap()});

    assert_eq!(
        client.get_json::<Value>("/v1/projects").await.unwrap(),
        json!({"items":[expected.clone()]})
    );
    assert_eq!(client.get_json::<Value>(&path).await.unwrap(), expected);

    // The response must remain registry-only even when Git cannot inspect the repository.
    std::fs::rename(&repo, directory.path().join("moved-repo")).unwrap();
    assert_eq!(
        client.get_json::<Value>("/v1/projects").await.unwrap(),
        json!({"items":[expected.clone()]})
    );
    assert_eq!(client.get_json::<Value>(&path).await.unwrap(), expected);

    assert!(matches!(
        client.get_json::<Value>("/v1/projects/missing").await,
        Err(TerminaldClientError::HttpStatus {
            status: StatusCode::NOT_FOUND,
            ..
        })
    ));
    assert!(matches!(
        client
            .post_json::<_, Value>("/v1/projects", &json!({}))
            .await,
        Err(TerminaldClientError::HttpStatus {
            status: StatusCode::METHOD_NOT_ALLOWED,
            ..
        })
    ));

    // Removing the registration is immediately reflected by both CLI queries.
    let response = app
        .oneshot(
            Request::delete(format!(
                "/api/aow/projects/{}",
                project["id"].as_str().unwrap()
            ))
            .body(Body::empty())
            .unwrap(),
        )
        .await
        .unwrap();
    assert!(response.status().is_success());
    assert_eq!(
        client.get_json::<Value>("/v1/projects").await.unwrap(),
        json!({"items":[]})
    );
    assert!(matches!(
        client.get_json::<Value>(&path).await,
        Err(TerminaldClientError::HttpStatus {
            status: StatusCode::NOT_FOUND,
            ..
        })
    ));
    server.shutdown().await;
}

use std::{
    net::{IpAddr, SocketAddr},
    path::PathBuf,
};

use anyhow::{Context, Result};
use aow_server::{AppState, BasePath, build_router, default_terminal_state_dir};
use aow_terminald_client::TerminaldClient;
use tracing_subscriber::EnvFilter;

fn main() -> Result<()> {
    #[cfg(target_os = "macos")]
    let unified = aow_macos_log::init_from_env(c"server", "aow=info,tower_http=info");
    #[cfg(not(target_os = "macos"))]
    let unified = false;
    if !unified {
        tracing_subscriber::fmt()
            .with_env_filter(
                EnvFilter::try_from_default_env()
                    .unwrap_or_else(|_| EnvFilter::new("aow=info,tower_http=info")),
            )
            .init();
    }
    let result = run();
    #[cfg(target_os = "macos")]
    if let Err(error) = &result {
        aow_macos_log::report_error(&format!("AOW server failed: {error:#}"));
    }
    result
}

#[tokio::main]
async fn run() -> Result<()> {
    let mut host = "127.0.0.1".to_owned();
    let mut port = 8282_u16;
    let mut frontend = PathBuf::from("frontend/dist");
    let mut base_path = std::env::var_os("AOW_BASE_PATH").unwrap_or_default();
    let mut state_dir = default_terminal_state_dir();
    let mut terminald_socket = TerminaldClient::default_socket_path();
    let mut initialize_only = false;
    let mut initialize_if_missing = false;
    let mut arguments = std::env::args().skip(1);
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--base-path" => {
                base_path = arguments
                    .next()
                    .context("--base-path requires a value")?
                    .into()
            }
            "--initialize-state" => initialize_only = true,
            "--initialize-state-if-missing" => {
                initialize_only = true;
                initialize_if_missing = true;
            }
            "--host" => host = arguments.next().context("--host requires a value")?,
            "--port" => {
                port = arguments
                    .next()
                    .context("--port requires a value")?
                    .parse()
                    .context("invalid --port")?;
            }
            "--frontend" => {
                frontend = PathBuf::from(arguments.next().context("--frontend requires a value")?);
            }
            "--state-dir" => {
                state_dir =
                    PathBuf::from(arguments.next().context("--state-dir requires a value")?);
            }
            "--terminald-socket" => {
                terminald_socket = PathBuf::from(
                    arguments
                        .next()
                        .context("--terminald-socket requires a value")?,
                );
            }
            "-h" | "--help" => {
                println!(
                    "Usage: aow-server [--host 127.0.0.1] [--port 8282] [--base-path PATH] [--frontend frontend/dist] [--state-dir PATH] [--terminald-socket PATH] [--initialize-state | --initialize-state-if-missing]\nHost: IPv4 or IPv6 address (for example 127.0.0.1 or ::1); default 127.0.0.1\nBase path: --base-path overrides AOW_BASE_PATH; default /"
                );
                return Ok(());
            }
            other => anyhow::bail!("unknown argument: {other}"),
        }
    }

    if initialize_only {
        if initialize_if_missing
            && let Some(config) = aow_config::ConfigRepository::open(&state_dir)?
            && config.directory().join("aow-projects.json").exists()
        {
            return Ok(());
        }
        aow_server::initialize_aow_state(&state_dir).await?;
        return Ok(());
    }
    let base_path = BasePath::parse(
        base_path
            .to_str()
            .context("base path must be valid UTF-8")?,
    )?;
    let address = listen_address(&host, port)?;
    let listener = tokio::net::TcpListener::bind(address).await?;
    let local = listener.local_addr()?;
    tracing::info!(%local, "aow listening");
    println!("AOW: http://{local}{}/", base_path.as_str());
    let state = AppState::with_runtime_options(frontend, state_dir.clone(), terminald_socket)?
        .with_base_path(base_path);
    state.initialize_global_workspace().await?;
    if let Err(error) = state.reconcile_terminals().await {
        tracing::warn!(%error, "initial terminald reconciliation failed; terminal requests will retry");
    }
    state.start_agent_notifications();
    let cli = aow_server::start_local_cli(state.clone(), &state_dir).await?;
    axum::serve(listener, build_router(state))
        .with_graceful_shutdown(shutdown_signal())
        .await
        .map_err(anyhow::Error::from)?;
    cli.shutdown().await;
    Ok(())
}

fn listen_address(host: &str, port: u16) -> Result<SocketAddr> {
    host.parse::<IpAddr>()
        .map(|ip| SocketAddr::new(ip, port))
        // Preserve bracketed IPv6 hosts accepted by the original CLI.
        .or_else(|_| format!("{host}:{port}").parse())
        .context("invalid listen address")
}

async fn shutdown_signal() {
    #[cfg(unix)]
    {
        let mut terminate =
            tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
                .expect("SIGTERM handler can be installed");
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {},
            _ = terminate.recv() => {},
        }
    }
    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
    }
}

#[cfg(test)]
mod tests {
    use super::listen_address;

    #[test]
    fn listen_addresses_accept_ipv4_and_both_ipv6_host_notations() {
        for (host, expected) in [
            ("127.0.0.1", "127.0.0.1:8282"),
            ("0.0.0.0", "0.0.0.0:8282"),
            ("::1", "[::1]:8282"),
            ("[::1]", "[::1]:8282"),
            ("::", "[::]:8282"),
            ("[::]", "[::]:8282"),
            ("2001:db8::10", "[2001:db8::10]:8282"),
            ("[2001:db8::10]", "[2001:db8::10]:8282"),
        ] {
            assert_eq!(listen_address(host, 8282).unwrap().to_string(), expected);
        }
        assert_eq!(listen_address("::1", 0).unwrap().port(), 0);
    }

    #[test]
    fn listen_address_rejects_invalid_hosts_without_broadening_the_bind() {
        for host in [
            "",
            "localhost",
            "127.0.0.1:8282",
            "[::1",
            "::1]",
            "not-an-ip",
        ] {
            assert!(listen_address(host, 8282).is_err(), "{host}");
        }
    }
}

//! Business events become transport-independent messages here.
use aow_im::{Field, Message};

use super::AutomationFailureNotification;
use crate::terminal::notifications::TaskStopNotification;

pub(super) fn task_completed(event: &TaskStopNotification) -> Message {
    let agent = aow_agents::Agent::from_id(&event.agent)
        .map(|agent| agent.definition().display_name)
        .unwrap_or(&event.agent);
    let mut projects = Vec::new();
    let mut fields = Vec::new();
    for source in &event.sources {
        let project = source.project_name.trim();
        if !project.is_empty() && !projects.contains(&project) {
            projects.push(project);
        }
        fields.push(Field {
            label: "Tab".into(),
            value: source.tab_name.clone(),
            url: source.tab_url.clone(),
        });
    }
    let project = if projects.is_empty() {
        "未命名项目".into()
    } else {
        projects.join("、")
    };
    fields.push(Field {
        label: "会话".into(),
        value: format!("{}\nSession ID：{}", event.title, event.session_id),
        url: None,
    });
    Message {
        title: format!("{project}·{}·{agent}·完成", event.title),
        fields,
        body_label: "本轮结论".into(),
        body: event
            .conclusion
            .as_deref()
            .filter(|text| !text.trim().is_empty())
            .unwrap_or("未捕获到本轮结论。")
            .into(),
        markdown: true,
        error: false,
    }
}

pub(super) fn automation_failure(event: &AutomationFailureNotification) -> Message {
    let run = &event.run;
    let mut fields = vec![Field {
        label: "任务".into(),
        value: format!(
            "{}\nAgent：{}\n任务 ID：{}\n执行 ID：{}\n结束时间：{}\n耗时：{}\n退出码：{}",
            run.task_name,
            run.agent.id(),
            run.task_id,
            run.id,
            run.finished_at
                .map(|at| at.to_rfc3339())
                .unwrap_or_else(|| "未知".into()),
            run.duration_ms
                .map(|ms| format!("{:.1} 秒", ms as f64 / 1000.0))
                .unwrap_or_else(|| "未知".into()),
            run.exit_code
                .map(|code| code.to_string())
                .unwrap_or_else(|| "无".into()),
        ),
        url: None,
    }];
    if let Some(url) = &event.run_url {
        fields.push(Field {
            label: "执行记录".into(),
            value: "查看执行记录".into(),
            url: Some(url.clone()),
        });
    }
    Message {
        title: format!("自动化失败 · {}", run.task_name),
        fields,
        body_label: "失败原因".into(),
        body: run
            .message
            .as_deref()
            .unwrap_or("未记录失败原因")
            .chars()
            .take(2000)
            .collect(),
        markdown: false,
        error: true,
    }
}

//! Local notification settings and dispatch, independent of agent implementations.
use std::{
    collections::HashSet,
    path::{Path, PathBuf},
    sync::{
        Arc, Mutex,
        atomic::{AtomicBool, Ordering},
    },
};

use axum::{
    Json, Router,
    extract::State,
    http::{StatusCode, header::CACHE_CONTROL},
    routing::get,
};
use serde::{Deserialize, Serialize};
use tokio::sync::{broadcast, mpsc};
use uuid::Uuid;

use crate::{
    AppState, HttpError,
    aow::{AowError, atomic_save_document},
    terminal::notifications::TaskStopNotification,
};

use aow_im::{ImConfig, ImConfigUpdate, ImConfigView, ImKind, ImProvider, Provider};

mod messages;

const FILE_NAME: &str = "notification-settings.json";
const QUEUE_CAPACITY: usize = 64;

pub(crate) struct AutomationFailureNotification {
    pub(crate) run: aow_automations::Run,
    pub(crate) run_url: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum Channel {
    Page,
    Feishu,
    Wechat,
}

impl Channel {
    fn provider(self) -> Option<ImKind> {
        match self {
            Self::Page => None,
            Self::Feishu => Some(ImKind::Feishu),
            Self::Wechat => Some(ImKind::Wechat),
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct TaskCompletedSettings {
    enabled: bool,
    channels: Vec<Channel>,
}

impl Default for TaskCompletedSettings {
    fn default() -> Self {
        Self {
            enabled: true,
            channels: vec![Channel::Page],
        }
    }
}

#[derive(Clone, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct ImSettings {
    providers: Vec<ImConfig>,
}

#[derive(Clone, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct NotificationSettings {
    agent_task_completed: TaskCompletedSettings,
    #[serde(default)]
    public_base_url: String,
}

#[derive(Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Document {
    version: u32,
    im: ImSettings,
    notifications: NotificationSettings,
}

impl Default for Document {
    fn default() -> Self {
        Self {
            version: 1,
            im: ImSettings::default(),
            notifications: NotificationSettings::default(),
        }
    }
}

impl Document {
    fn validate(&self) -> Result<(), String> {
        if self.version != 1 {
            return Err("不支持的通知配置版本".into());
        }
        normalize_public_base_url(&self.notifications.public_base_url)?;
        let mut providers = HashSet::new();
        for provider in &self.im.providers {
            provider.validate()?;
            if !providers.insert(provider.kind()) {
                return Err("IM 配置重复".into());
            }
        }
        let settings = &self.notifications.agent_task_completed;
        if settings.enabled && settings.channels.is_empty() {
            return Err("启用 Agent 任务完成通知后，至少选择一种通知方式".into());
        }
        let mut channels = HashSet::new();
        for channel in &settings.channels {
            if !channels.insert(channel) {
                return Err("通知方式重复".into());
            }
            if let Some(kind) = channel.provider()
                && !providers.contains(&kind)
            {
                let name = if kind == ImKind::Feishu {
                    "飞书"
                } else {
                    "微信"
                };
                return Err(format!(
                    "请先配置{name}机器人；移除机器人前请取消选择{name}推送"
                ));
            }
        }
        Ok(())
    }

    pub(crate) fn view(&self) -> SettingsView {
        SettingsView {
            im: ImSettingsView {
                providers: self.im.providers.iter().map(ImConfig::view).collect(),
            },
            notifications: self.notifications.clone(),
        }
    }
}

#[derive(Serialize)]
struct ImSettingsView {
    providers: Vec<ImConfigView>,
}

#[derive(Serialize)]
pub(crate) struct SettingsView {
    im: ImSettingsView,
    notifications: NotificationSettings,
}

#[derive(Deserialize)]
#[serde(tag = "section", rename_all = "snake_case", deny_unknown_fields)]
pub(crate) enum SettingsUpdate {
    ImProvider {
        config: ImConfigUpdate,
    },
    ImRemove {
        provider: ImKind,
    },
    #[serde(skip)]
    WechatBinding {
        credentials: aow_im::wechat::Credentials,
    },
    Im {
        providers: Vec<ImConfigUpdate>,
    },
    Notifications {
        agent_task_completed: TaskCompletedSettings,
        // Older clients only update delivery preferences and preserve the URL.
        public_base_url: Option<String>,
    },
}

struct ConfiguredProvider {
    config: ImConfig,
    provider: Provider,
}

struct RuntimeState {
    document: Document,
    providers: Vec<ConfiguredProvider>,
    revision: u64,
}

struct Delivery {
    event: TaskStopNotification,
    revision: u64,
    id: String,
}

struct Inner {
    path: Option<PathBuf>,
    started: AtomicBool,
    wechat_login: aow_im::wechat::LoginManager,
    state: Mutex<RuntimeState>,
    sender: mpsc::Sender<Delivery>,
    receiver: Mutex<Option<mpsc::Receiver<Delivery>>>,
}

#[derive(Clone)]
pub(crate) struct NotificationManager {
    inner: Arc<Inner>,
}

impl NotificationManager {
    /// Automation preferences belong to the run snapshot, independently of
    /// interactive Agent completion preferences. False means no local bot.
    pub(crate) async fn send_automation_failure(
        &self,
        run: aow_automations::Run,
        channel: aow_automations::FailureNotification,
        delivery_id: &str,
    ) -> anyhow::Result<bool> {
        let Some((provider, event)) = self.automation_delivery(run, channel) else {
            return Ok(false);
        };
        provider
            .send(&messages::automation_failure(&event), delivery_id)
            .await?;
        Ok(true)
    }

    fn automation_delivery(
        &self,
        run: aow_automations::Run,
        channel: aow_automations::FailureNotification,
    ) -> Option<(Provider, AutomationFailureNotification)> {
        let (provider, base_url) = {
            let state = self.inner.state.lock().unwrap();
            (
                state
                    .providers
                    .iter()
                    .find(|provider| {
                        provider.config.kind()
                            == match channel {
                                aow_automations::FailureNotification::Feishu => ImKind::Feishu,
                                aow_automations::FailureNotification::Wechat => ImKind::Wechat,
                            }
                    })
                    .map(|provider| provider.provider.clone()),
                state.document.notifications.public_base_url.clone(),
            )
        };
        let provider = provider?;
        let run_url = reqwest::Url::parse(&base_url).ok().and_then(|mut url| {
            url.path_segments_mut().ok()?.pop_if_empty().extend([
                "aow",
                "tabs",
                "automation",
                &run.task_id,
                "runs",
                &run.id,
            ]);
            Some(url.into())
        });
        Some((provider, AutomationFailureNotification { run, run_url }))
    }

    pub(crate) fn in_memory() -> Self {
        Self::new(None, Document::default()).expect("empty configuration is valid")
    }

    pub(crate) fn persistent(state_dir: &Path) -> Result<Self, AowError> {
        let path = state_dir.join(FILE_NAME);
        let document = match std::fs::read(&path) {
            Ok(bytes) => serde_json::from_slice(&bytes)?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Document::default(),
            Err(error) => return Err(error.into()),
        };
        Self::new(Some(path), document)
    }

    fn new(path: Option<PathBuf>, document: Document) -> Result<Self, AowError> {
        document.validate().map_err(AowError::Invalid)?;
        let providers = build_providers(
            &document.im.providers,
            &[],
            path.as_deref().and_then(Path::parent),
        )?;
        let (sender, receiver) = mpsc::channel(QUEUE_CAPACITY);
        Ok(Self {
            inner: Arc::new(Inner {
                path,
                started: AtomicBool::new(false),
                wechat_login: aow_im::wechat::LoginManager::new()
                    .map_err(AowError::Configuration)?,
                state: Mutex::new(RuntimeState {
                    document,
                    providers,
                    revision: 0,
                }),
                sender,
                receiver: Mutex::new(Some(receiver)),
            }),
        })
    }

    pub(crate) fn view(&self) -> SettingsView {
        self.inner.state.lock().unwrap().document.view()
    }

    pub(crate) fn update(&self, update: SettingsUpdate) -> Result<SettingsView, AowError> {
        let mut state = self.inner.state.lock().unwrap();
        let mut next = state.document.clone();
        match update {
            SettingsUpdate::WechatBinding { credentials } => {
                next.im
                    .providers
                    .retain(|config| config.kind() != ImKind::Wechat);
                next.im.providers.push(ImConfig::Wechat { credentials });
            }
            SettingsUpdate::ImProvider { config } => {
                let config = config
                    .resolve(&state.document.im.providers)
                    .map_err(AowError::Invalid)?;
                next.im.providers.retain(|old| old.kind() != config.kind());
                next.im.providers.push(config);
            }
            SettingsUpdate::ImRemove { provider } => {
                next.im.providers.retain(|config| config.kind() != provider);
            }
            SettingsUpdate::Im { providers } => {
                next.im.providers = providers
                    .into_iter()
                    .map(|update| update.resolve(&state.document.im.providers))
                    .collect::<Result<_, _>>()
                    .map_err(AowError::Invalid)?;
                // Legacy clients replace the Feishu list. They cannot disconnect
                // a QR binding that was added after they loaded their settings.
                if !next
                    .im
                    .providers
                    .iter()
                    .any(|config| config.kind() == ImKind::Wechat)
                {
                    next.im.providers.extend(
                        state
                            .document
                            .im
                            .providers
                            .iter()
                            .filter(|config| config.kind() == ImKind::Wechat)
                            .cloned(),
                    );
                }
            }
            SettingsUpdate::Notifications {
                agent_task_completed,
                public_base_url,
            } => {
                next.notifications.agent_task_completed = agent_task_completed;
                if let Some(url) = public_base_url {
                    next.notifications.public_base_url =
                        normalize_public_base_url(&url).map_err(AowError::Invalid)?;
                }
            }
        }
        next.validate().map_err(AowError::Invalid)?;
        let providers = build_providers(
            &next.im.providers,
            &state.providers,
            self.inner.path.as_deref().and_then(Path::parent),
        )?;
        if let Some(path) = &self.inner.path {
            atomic_save_document(path, &next)?;
        }
        for previous in &state.providers {
            if !next.im.providers.contains(&previous.config) {
                previous.provider.retire();
            }
        }
        if self.inner.started.load(Ordering::Relaxed) {
            for configured in &providers {
                configured.provider.start();
            }
        }
        state.document = next;
        state.providers = providers;
        state.revision += 1;
        Ok(state.document.view())
    }

    pub(crate) fn wechat_login(&self) -> &aow_im::wechat::LoginManager {
        &self.inner.wechat_login
    }

    pub(crate) fn wechat_credentials(&self) -> Option<aow_im::wechat::Credentials> {
        self.inner
            .state
            .lock()
            .unwrap()
            .document
            .im
            .providers
            .iter()
            .find_map(|config| match config {
                ImConfig::Wechat { credentials } => Some(credentials.clone()),
                _ => None,
            })
    }

    pub(crate) fn wechat(&self) -> Option<Arc<aow_im::wechat::WechatClient>> {
        self.inner
            .state
            .lock()
            .unwrap()
            .providers
            .iter()
            .find_map(|config| match &config.provider {
                Provider::Wechat(client) => Some(client.clone()),
                _ => None,
            })
    }

    pub(crate) fn start(&self) {
        self.inner.started.store(true, Ordering::Relaxed);
        for configured in &self.inner.state.lock().unwrap().providers {
            configured.provider.start();
        }
        let Some(mut receiver) = self.inner.receiver.lock().unwrap().take() else {
            return;
        };
        let weak = Arc::downgrade(&self.inner);
        tokio::spawn(async move {
            while let Some(delivery) = receiver.recv().await {
                let Some(inner) = weak.upgrade() else {
                    break;
                };
                let providers: Vec<_> = {
                    let state = inner.state.lock().unwrap();
                    let settings = &state.document.notifications.agent_task_completed;
                    // Settings changes invalidate queued deliveries, including changed credentials.
                    if state.revision != delivery.revision || !settings.enabled {
                        continue;
                    }
                    settings
                        .channels
                        .iter()
                        .filter_map(|channel| channel.provider())
                        .filter_map(|kind| {
                            state
                                .providers
                                .iter()
                                .find(|provider| provider.config.kind() == kind)
                        })
                        .map(|provider| (provider.config.kind(), provider.provider.clone()))
                        .collect()
                };
                drop(inner);
                for (kind, provider) in providers {
                    if let Err(error) = provider
                        .send(&messages::task_completed(&delivery.event), &delivery.id)
                        .await
                    {
                        tracing::warn!(provider = ?kind, session_id = %delivery.event.session_id, %error, "agent notification delivery failed");
                    }
                }
            }
        });
    }

    pub(crate) fn dispatch(
        &self,
        mut event: TaskStopNotification,
        page: &broadcast::Sender<TaskStopNotification>,
    ) {
        let state = self.inner.state.lock().unwrap();
        let settings = &state.document.notifications.agent_task_completed;
        if !settings.enabled {
            return;
        }
        if let Ok(base) = reqwest::Url::parse(&state.document.notifications.public_base_url) {
            for source in &mut event.sources {
                let mut url = base.clone();
                if let Ok(mut segments) = url.path_segments_mut() {
                    segments
                        .pop_if_empty()
                        .extend(["aow", "tabs", "terminal", &source.tab_id]);
                }
                source.tab_url = Some(url.into());
            }
        }
        if settings.channels.contains(&Channel::Page) {
            let _ = page.send(event.clone());
        }
        if settings
            .channels
            .iter()
            .any(|channel| channel.provider().is_some())
        {
            let delivery = Delivery {
                event,
                revision: state.revision,
                id: Uuid::new_v4().to_string(),
            };
            if self.inner.sender.try_send(delivery).is_err() {
                tracing::warn!("IM notification queue full or closed; delivery dropped");
            }
        }
    }
}

fn normalize_public_base_url(value: &str) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(String::new());
    }
    let invalid =
        || "请填写有效的 AOW HTTP(S) 部署地址，可含 Base Path，不含账号、查询参数或片段".to_owned();
    let url = reqwest::Url::parse(value).map_err(|_| invalid())?;
    if value.len() > 2048
        || !matches!(url.scheme(), "http" | "https")
        || url.host_str().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
    {
        return Err(invalid());
    }
    let base = crate::BasePath::parse(url.path()).map_err(|_| invalid())?;
    Ok(format!(
        "{}{}",
        url.origin().ascii_serialization(),
        base.as_str()
    ))
}

fn build_providers(
    configs: &[ImConfig],
    previous: &[ConfiguredProvider],
    state_dir: Option<&Path>,
) -> Result<Vec<ConfiguredProvider>, AowError> {
    configs
        .iter()
        .map(|config| {
            let provider = match previous.iter().find(|old| old.config == *config) {
                Some(old) => old.provider.clone(),
                None => config.build(state_dir).map_err(AowError::Configuration)?,
            };
            Ok(ConfiguredProvider {
                config: config.clone(),
                provider,
            })
        })
        .collect()
}

pub(crate) fn routes() -> Router<AppState> {
    Router::new().route(
        "/api/aow/notification-settings",
        get(get_settings).put(update_settings),
    )
}

async fn get_settings(State(state): State<AppState>) -> impl axum::response::IntoResponse {
    (
        [(CACHE_CONTROL, "no-store")],
        Json(state.aow.notifications().view()),
    )
}

async fn update_settings(
    State(state): State<AppState>,
    Json(update): Json<SettingsUpdate>,
) -> Result<impl axum::response::IntoResponse, HttpError> {
    let manager = state.aow.notifications().clone();
    let settings = tokio::task::spawn_blocking(move || manager.update(update))
        .await
        .map_err(|_| {
            HttpError::new(
                StatusCode::INTERNAL_SERVER_ERROR,
                "notification_settings_failed",
                "无法保存通知配置",
                None,
            )
        })?
        .map_err(crate::aow::aow_http_error)?;
    Ok(([(CACHE_CONTROL, "no-store")], Json(settings)))
}

