      name: basename(path),
      path,
      kind: 'file',
      size: 0,
      modified_ms: null,
      readonly: false,
      hidden: false,
      mode: 0,
      links: 1,
      uid: 0,
      gid: 0,
      is_symlink: false,
      link_target: null,
