interface ContextMenuState { x: number; y: number; path: string; displayPath: string; directory: boolean; renameable: boolean }
interface RenameState { path: string; draft: string; busy: boolean }
interface CreationState { parent: string; kind: 'file' | 'directory'; draft: string; busy: boolean }
type DisplayRow = { type: 'root' } | { type: 'parent'; path: string } | { type: 'entry'; node: TreeNode } | { type: 'creation'; depth: number };
type VirtualRowData = { render: (props: ListChildComponentProps) => ReactNode; rows: DisplayRow[] };

// Keep the component identity and row keys stable during upload progress and
// directory refreshes, so an active rename input retains its draft and focus.
function VirtualRow(props: ListChildComponentProps<VirtualRowData>) {
  return props.data.render(props);
}

function virtualRowKey(index: number, data: VirtualRowData) {
  const row = data.rows[index];
  return row.type === 'entry' ? row.node.path : row.type;
}

function flatten(nodes: TreeNode[]): TreeNode[] {
  return nodes.flatMap((node) => [node, ...(node.expanded && node.children ? flatten(node.children) : [])]);
}

function updateNode(nodes: TreeNode[], path: string, update: (node: TreeNode) => TreeNode): TreeNode[] {
  return nodes.map((node) => node.path === path
    ? update(node)
    : node.children ? { ...node, children: updateNode(node.children, path, update) } : node);
}

function expandToDirectory(nodes: TreeNode[], directory: string): TreeNode[] {
  return nodes.map((node) => node.kind === 'directory' && (node.path === directory || directory.startsWith(`${node.path}/`))
    ? { ...node, expanded: true, children: node.children ? expandToDirectory(node.children, directory) : undefined }
    : node);
}

function preserveTreeState(nodes: TreeNode[], previousNodes: TreeNode[]): TreeNode[] {
  const previousByPath = new Map(previousNodes.map((node) => [node.path, node]));
  return nodes.map((node) => {
    const previous = previousByPath.get(node.path);
    if (node.kind !== 'directory' || previous?.kind !== 'directory') return node;
    return {
      ...node,
      expanded: previous.expanded,
      loading: node.children ? false : previous.loading,
      children: node.children ? preserveTreeState(node.children, previous.children ?? []) : previous.children,
    };
  });
}

async function loadTreeNodes(root: string, path: string, depth: number, previousNodes: TreeNode[] = []): Promise<TreeNode[]> {
  const listing = await filesApi.listDirectory(path);
  const entries = listing.entries.filter((entry) => entry.name !== '.git');
  const paths = entries.map((entry) => entry.path);
  const ignored = paths.length > 0
    ? await gitApi.gitIgnored(root, paths).then((result) => new Set(result.ignored)).catch(() => new Set<string>())
    : new Set<string>();
  const previousByPath = new Map(previousNodes.map((node) => [node.path, node]));
  return Promise.all(entries.map(async (entry) => {
    const previous = previousByPath.get(entry.path);
    const directory = entry.kind === 'directory' && previous?.kind === 'directory';
    return {
      ...entry,
      depth,
      expanded: directory && previous.expanded,
      loading: false,
      ignored: ignored.has(entry.path),
      // Refresh loaded branches too, preserving nested expansion under collapsed parents.
      children: directory && (previous.expanded || previous.children || previous.loading)
        ? await loadTreeNodes(root, entry.path, depth + 1, previous.children)
        : undefined,
    };
  }));
}

export function Explorer({ root, activePath, onRootChange, onOpenFile, onRenameFile, onCreateFile, onCreateDirectory, onDeleteEntry, refreshRequest, lockedRoot = false, titleCase = false, title, titleIcon, aowHeader = false, collapsed: controlledCollapsed, onCollapsedChange, renameDirectories = false }: Props) {
  const [nodes, setNodes] = useState<TreeNode[]>([]);
  const [error, setError] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [height, setHeight] = useState(1);
  const [rootExpanded, setRootExpanded] = useState(true);
  const [rootLoading, setRootLoading] = useState(true);
  const [collapsed, changeCollapsed] = usePanelCollapsed(aowHeader && !rootLoading && !error && nodes.length === 0, controlledCollapsed, onCollapsedChange);
  const [contextMenu, setContextMenu] = useState<ContextMenuState>();
  const [rename, setRename] = useState<RenameState>();
  const [creation, setCreation] = useState<CreationState>();
  const [status, setStatus] = useState('');
  const [selection, setSelection] = useState<{ path: string; directory: string }>();
  const [pasteHint, setPasteHint] = useState<{ directory: string; message: string }>();
  const [revealedPath, setRevealedPath] = useState<string>();
  const virtualList = useRef<FixedSizeList>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const fileInputDestination = useRef(root);
  const clipboardGeneration = useRef(0);
  const handledRefresh = useRef(0);
  const cancelRename = useRef(false);
  const cancelCreation = useRef(false);
  const treeList = useRef<HTMLDivElement>(null);
  const nodesRef = useRef(nodes);
  const loadedRoot = useRef(root);
  const treeGeneration = useRef(0);

  useLayoutEffect(() => { nodesRef.current = nodes; }, [nodes]);

  useLayoutEffect(() => {
    const element = treeList.current;
    if (!element) return;
    const resize = () => setHeight(Math.max(1, Math.floor(element.getBoundingClientRect().height)));
    resize();
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', resize);
      return () => window.removeEventListener('resize', resize);
    }
    const observer = new ResizeObserver(resize);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useLayoutEffect(() => {
    setRootExpanded(true); setRename(undefined); setCreation(undefined);
    setSelection(undefined); setPasteHint(undefined); setContextMenu(undefined); setRevealedPath(undefined);
    return () => { clipboardGeneration.current += 1; };
  }, [root]);

  useEffect(() => {
    let cancelled = false;
    const rootChanged = loadedRoot.current !== root;
    const previousNodes = rootChanged ? [] : nodesRef.current;
    loadedRoot.current = root;
    if (rootChanged) setNodes([]);
    setError(''); setRootLoading(true);
    loadTreeNodes(root, root, 0, previousNodes).then((entries) => {
      if (!cancelled) {
        setNodes((current) => preserveTreeState(entries, current));
        setRootLoading(false);
      }
    }).catch((reason: Error) => { if (!cancelled) { setError(reason.message); setRootLoading(false); } });
    return () => { cancelled = true; treeGeneration.current += 1; };
  }, [root, refreshKey]);

  const rows = useMemo(() => flatten(nodes), [nodes]);
  const parentPath = useMemo(() => {
    if (!root || root === '/') return undefined;
    const normalized = root.endsWith('/') ? root.slice(0, -1) : root;
    const index = normalized.lastIndexOf('/');
    return index <= 0 ? '/' : normalized.slice(0, index);
  }, [root]);
  const rootName = useMemo(() => {
    if (root === '/') return '/';
    const normalized = root.endsWith('/') ? root.slice(0, -1) : root;
    return normalized.split('/').pop() || root;
  }, [root]);
  const displayRows = useMemo<DisplayRow[]>(() => {
    const result: DisplayRow[] = [{ type: 'root' }];
    if (!rootExpanded) return result;
    if (parentPath && !lockedRoot) result.push({ type: 'parent', path: parentPath });
    if (creation?.parent === root) result.push({ type: 'creation', depth: 0 });
    const appendEntries = (entries: TreeNode[]) => {
      for (const node of entries) {
        result.push({ type: 'entry', node });
        if (creation?.parent === node.path) result.push({ type: 'creation', depth: node.depth + 1 });
        if (node.expanded && node.children) appendEntries(node.children);
      }
    };
    appendEntries(nodes);
    return result;
  }, [creation, lockedRoot, nodes, parentPath, root, rootExpanded]);
  const panelList = usePanelListViewport(displayRows.length, 24, aowHeader && !collapsed);
  const reloadDirectory = useCallback(async (path: string) => {
    const generation = treeGeneration.current;
    if (path === root) {
      const entries = await loadTreeNodes(root, root, 0, nodesRef.current);
      if (generation !== treeGeneration.current) return;
      setNodes((current) => preserveTreeState(entries, current));
      return;
    }
    const target = rows.find((node) => node.path === path);
    if (!target) { setRefreshKey((key) => key + 1); return; }
    const entries = await loadTreeNodes(root, path, target.depth + 1, target.children);
    if (generation !== treeGeneration.current) return;
    setNodes((current) => updateNode(current, path, (item) => ({
      ...item, loading: false,
      children: preserveTreeState(entries, item.children ?? []),
    })));
  }, [root, rows]);

  const upload = useExplorerUploads(root, async (directory, path) => {
    const generation = clipboardGeneration.current;
    const expanded = expandToDirectory(nodesRef.current, directory);
    setRootExpanded(true);
    setNodes(expanded);
    const entries = await loadTreeNodes(root, root, 0, expanded);
    if (generation !== clipboardGeneration.current) return;
    setNodes((current) => expandToDirectory(preserveTreeState(entries, current), directory));
    setRevealedPath(path);
  });
  const uploading = upload.uploads.some((item) => item.status === 'waiting' || item.status === 'uploading');

  useLayoutEffect(() => {
    if (!revealedPath) return;
    const index = displayRows.findIndex((row) => row.type === 'entry' && row.node.path === revealedPath);
    if (index >= 0) {
      if (aowHeader) panelList.reveal(index);
      else virtualList.current?.scrollToItem(index, 'smart');
    }
  }, [displayRows, revealedPath, aowHeader, panelList.reveal]);

  const enqueueFiles = (directory: string, files: File[]) => {
    setPasteHint(undefined);
    setError('');
    setStatus('');
    upload.enqueue(directory, files);
  };

  const paste = (event: ClipboardEvent<HTMLElement>) => {
    if (isEditableTarget(event.target) || collapsed || rename || creation) return;
    try {
      // Read File objects synchronously while the native paste data is available.
      const { files, hasDirectories } = pastedFiles(event.clipboardData);
      if (!files.length && !hasDirectories) {
        if (pasteHint) setPasteHint({ ...pasteHint, message: '剪贴板中没有可上传的文件或图片，请选择文件上传。' });
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      const directory = pasteHint?.directory ?? selection?.directory ?? root;
      setContextMenu(undefined);
      enqueueFiles(directory, files);
      if (hasDirectories) setError('暂不支持整目录粘贴，请选择目录中的文件。');
    } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); }
  };

  const pasteFromMenu = async (directory: string) => {
    const generation = clipboardGeneration.current;
    treeList.current?.focus({ preventScroll: true });
    setSelection({ path: directory, directory });
    setError('');
    setStatus('');
    setPasteHint(undefined);
    const fallback = (message: string) => {
      if (generation !== clipboardGeneration.current) return;
      setPasteHint({ directory, message });
      treeList.current?.focus({ preventScroll: true });
    };
    if (!window.isSecureContext || !navigator.clipboard?.read) {
      fallback('浏览器无法直接读取剪贴板，请按 Ctrl/Cmd+V 粘贴，或选择文件上传。');
      return;
    }
    try {
      const files = await readClipboardImages();
      if (generation !== clipboardGeneration.current) return;
      if (files.length) enqueueFiles(directory, files);
      else fallback('请按 Ctrl/Cmd+V 粘贴文件，或选择文件上传。');
    } catch {
      fallback('无法读取剪贴板，请按 Ctrl/Cmd+V 粘贴，或选择文件上传。');
    }
  };

  const showContextMenu = (event: MouseEvent, target: Omit<ContextMenuState, 'x' | 'y'>) => {
    event.preventDefault();
    event.stopPropagation();
    const directory = target.directory ? target.path : target.path.slice(0, target.path.lastIndexOf('/')) || '/';
    setSelection({ path: target.path, directory });
    setPasteHint(undefined);
    treeList.current?.focus({ preventScroll: true });
    setContextMenu({ ...target, x: event.clientX, y: event.clientY });
  };

  const beginRename = (path: string) => {
    cancelRename.current = false;
    setError('');
    setStatus('');
    setRename({ path, draft: path.split('/').filter(Boolean).pop() ?? path, busy: false });
  };

  const finishRename = async (requestedName: string) => {
    const current = rename;
    if (!current || current.busy) return;
    if (cancelRename.current) {
      cancelRename.current = false;
      setRename(undefined);
      return;
    }
    const nextName = requestedName.trim();
    const oldName = current.path.split('/').filter(Boolean).pop() ?? current.path;
    if (nextName === oldName) { setRename(undefined); return; }
    if (!onRenameFile) { setRename(undefined); return; }
    const pending = { ...current, draft: requestedName, busy: true };
    setRename(pending);
    setError('');
    try {
      const result = await onRenameFile(current.path, nextName);
      setRename(undefined);
      setStatus(`已重命名为 ${result.name}`);
    } catch (reason) {
      setRename({ ...pending, busy: false });
      setError(reason instanceof Error ? reason.message : String(reason));
    }
  };

  const beginCreation = (parent: string, kind: CreationState['kind']) => {
    if (creation?.busy) return;
    cancelCreation.current = false;
    setError('');
    setStatus('');
    setRename(undefined);
    setCreation({ parent, kind, draft: '', busy: false });
    if (parent === root) {
      setRootExpanded(true);
      return;
    }
    const target = rows.find((node) => node.path === parent);
    if (!target || target.kind !== 'directory') return;
    setNodes((current) => updateNode(current, parent, (item) => ({ ...item, expanded: true })));
  };

  const finishCreation = async (requestedName: string) => {
    const current = creation;
    if (!current || current.busy) return;
    if (cancelCreation.current) {
      cancelCreation.current = false;
      setCreation(undefined);
      return;
    }
    const name = requestedName.trim();
    if (!name) {
      setCreation(undefined);
      return;
    }
    const create = current.kind === 'file' ? onCreateFile : onCreateDirectory;
    if (!create) {
      setCreation(undefined);
      return;
    }
    const pending = { ...current, draft: requestedName, busy: true };
    setCreation(pending);
    setError('');
    try {
      await create(current.parent, name);
      await reloadDirectory(current.parent);
      setCreation(undefined);
    } catch (reason) {
      setCreation({ ...pending, busy: false });
      setError(reason instanceof Error ? reason.message : String(reason));
    }
  };

  useEffect(() => {
    if (!refreshRequest.generation || refreshRequest.generation <= handledRefresh.current) return;
    handledRefresh.current = refreshRequest.generation;
    void reloadDirectory(refreshRequest.directory).catch((reason: Error) => setError(reason.message));
  }, [refreshRequest, reloadDirectory]);

  const copyText = useCallback(async (text: string) => {
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
      } else {
        const input = document.createElement('textarea');
        input.value = text; input.readOnly = true; input.style.position = 'fixed'; input.style.opacity = '0';
        document.body.appendChild(input); input.select();
        if (!document.execCommand('copy')) throw new Error('浏览器拒绝复制操作');
        input.remove();
      }
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
    }
  }, []);

  const downloadFile = useCallback((path: string) => {
    const link = document.createElement('a');
    link.href = filesApi.rawUrl(path);
    link.download = path.split('/').filter(Boolean).pop() ?? 'download';
    document.body.appendChild(link);
    link.click();
    link.remove();
  }, []);

  const toggle = useCallback(async (node: TreeNode) => {
    if (node.kind !== 'directory') { onOpenFile(node); return; }
    if (node.expanded) {
      setNodes((current) => updateNode(current, node.path, (item) => ({ ...item, expanded: false }))); return;
    }
    if (node.children) {
      setNodes((current) => updateNode(current, node.path, (item) => ({ ...item, expanded: true }))); return;
    }
    setNodes((current) => updateNode(current, node.path, (item) => ({ ...item, expanded: true, loading: true })));
    const generation = treeGeneration.current;
    try {
      const entries = await loadTreeNodes(root, node.path, node.depth + 1);
      if (generation !== treeGeneration.current) return;
      setNodes((current) => updateNode(current, node.path, (item) => ({
        ...item, loading: false, children: entries,
      })));
    } catch (reason) {
      if (generation !== treeGeneration.current) return;
      setError(reason instanceof Error ? reason.message : String(reason));
      setNodes((current) => updateNode(current, node.path, (item) => ({ ...item, expanded: false, loading: false })));
    }
  }, [onOpenFile, root]);

  const Row = ({ index, style }: ListChildComponentProps) => {
    const row = displayRows[index];
    if (row.type === 'root') {
      return <div
        style={{ ...style, paddingLeft: 5 }}
        className="tree-row workspace-root-node"
        data-tree-path={root} data-tree-directory={root}
        title={root}
        onClick={() => setRootExpanded((value) => !value)}
        onContextMenu={(event) => showContextMenu(event, { path: root, displayPath: root, directory: true, renameable: false })}
      >
        <span className={`chevron ${rootExpanded ? 'expanded' : ''}`}><ChevronRight size={13} /></span>
        <DirectoryTypeIcon expanded={rootExpanded} />
        <span className="tree-label">{rootName}</span>
        {rootLoading ? <span className="tree-busy">…</span> : null}
      </div>;
    }
    if (row.type === 'parent') {
      return <div style={{ ...style, paddingLeft: 19 }} className="tree-row parent-workspace-node" title={`上级目录：${row.path}`} onClick={() => onRootChange(row.path)}>
        <span className="chevron" />
        <FolderUp className="parent-folder" />
        <span className="tree-label">..</span>
      </div>;
    }
    if (row.type === 'creation') {
      if (!creation) return null;
      const directory = creation.kind === 'directory';
      return <div
        style={{ ...style, paddingLeft: 19 + row.depth * 14 }}
        className="tree-row tree-new-entry"
        onClick={(event) => event.stopPropagation()}
        onPointerDown={(event) => event.stopPropagation()}
      >
        <span className="chevron" />
        {directory ? <DirectoryTypeIcon /> : <FileTypeIcon path="untitled" />}
        <input
          className="tree-rename-input"
          value={creation.draft}
          maxLength={255}
          autoFocus
          aria-label={directory ? '新目录名' : '新文件名'}
          disabled={creation.busy}
          onChange={(event) => {
            const draft = event.currentTarget.value;
            setCreation((current) => current ? { ...current, draft } : current);
          }}
          onClick={(event) => event.stopPropagation()}
          onDoubleClick={(event) => event.stopPropagation()}
          onContextMenu={(event) => event.stopPropagation()}
          onBlur={(event) => void finishCreation(event.currentTarget.value)}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === 'Enter') event.currentTarget.blur();
            if (event.key === 'Escape') { cancelCreation.current = true; event.currentTarget.blur(); }
          }}
        />
        {creation.busy ? <span className="tree-busy">…</span> : null}
      </div>;
    }
    const node = row.node; const directory = node.kind === 'directory';
    return (
      <div
        style={{ ...style, paddingLeft: 19 + node.depth * 14 }}
        className={`tree-row${node.ignored ? ' git-ignored' : ''}${(selection?.path ?? activePath) === node.path ? ' selected' : ''}${revealedPath === node.path ? ' uploaded' : ''}`}
        data-tree-path={node.path} data-tree-directory={directory ? node.path : node.path.slice(0, node.path.lastIndexOf('/')) || '/'}
        title={node.path}
        onClick={() => toggle(node)}
        onContextMenu={(event) => showContextMenu(event, { path: node.path, displayPath: node.path, directory, renameable: node.kind === 'file' || (renameDirectories && directory) })}
      >
        <span className={`chevron ${directory && node.expanded ? 'expanded' : ''}`}>{directory ? <ChevronRight size={13} /> : null}</span>
        {directory ? <DirectoryTypeIcon expanded={node.expanded} /> : <FileTypeIcon path={node.path} />}
        {rename?.path === node.path ? <input
          className="tree-rename-input"
          defaultValue={rename.draft}
          maxLength={255}
          autoFocus
          aria-label="新文件名"
          disabled={rename.busy}
          onFocus={(event) => event.currentTarget.select()}
          onClick={(event) => event.stopPropagation()}
          onDoubleClick={(event) => event.stopPropagation()}
          onPointerDown={(event) => event.stopPropagation()}
          onContextMenu={(event) => event.stopPropagation()}
          onBlur={(event) => void finishRename(event.currentTarget.value)}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === 'Enter') event.currentTarget.blur();
            if (event.key === 'Escape') { cancelRename.current = true; event.currentTarget.blur(); }
          }}
        /> : <span className="tree-label">{node.name}</span>}{node.loading || (rename?.path === node.path && rename.busy) ? <span className="tree-busy">…</span> : null}
      </div>
    );
  };

  const content = <>
      <div className="explorer-body" hidden={collapsed}>
        {!lockedRoot ? <div className="root-controls">
          <button title="系统根目录" onClick={() => onRootChange('/')}>/</button>
        </div> : null}
        {error ? <div className="side-error">{error}</div> : null}
        {status ? <div className="explorer-status">{status}</div> : null}
        {pasteHint ? <div className="explorer-paste-hint" role="status">
          <span>{pasteHint.message}</span><small title={pasteHint.directory}>上传到：{pasteHint.directory}</small>
          <button onClick={() => { fileInputDestination.current = pasteHint.directory; fileInput.current?.click(); }}>选择文件上传</button>
          <button aria-label="取消粘贴" onClick={() => setPasteHint(undefined)}>取消</button>
        </div> : null}
        <input ref={fileInput} type="file" multiple hidden aria-label="选择粘贴上传文件" onChange={(event) => {
          const files = Array.from(event.currentTarget.files ?? []);
          event.currentTarget.value = '';
          if (files.length && (fileInputDestination.current === root || fileInputDestination.current.startsWith(root === '/' ? '/' : `${root}/`))) {
            enqueueFiles(fileInputDestination.current, files);
          }
        }} />
        <div ref={treeList} className="tree-list" tabIndex={0} aria-label={`${title ?? 'Explorer'} 文件树`}
          onPointerDown={(event) => {
            if (isEditableTarget(event.target)) return;
            treeList.current?.focus({ preventScroll: true });
          }}
          onClick={(event) => {
            if (isEditableTarget(event.target)) return;
            const row = (event.target as HTMLElement).closest<HTMLElement>('[data-tree-path]');
            setSelection({ path: row?.dataset.treePath ?? root, directory: row?.dataset.treeDirectory ?? root });
            setPasteHint(undefined); setRevealedPath(undefined);
          }}
          onContextMenu={(event) => showContextMenu(event, { path: root, displayPath: root, directory: true, renameable: false })}
        >
          {aowHeader ? <div ref={panelList.host} className="aow-panel-virtual-list" style={{ height: displayRows.length * 24 }}>
            {displayRows.slice(panelList.start, panelList.end).map((row, offset) => {
              const index = panelList.start + offset;
              return <VirtualRow key={row.type === 'entry' ? row.node.path : row.type} index={index}
                style={{ position: 'absolute', top: index * 24, height: 24, width: '100%' }} data={{ render: Row, rows: displayRows }} />;
            })}
          </div> : <FixedSizeList ref={virtualList} height={height} width="100%" itemCount={displayRows.length} itemSize={24}
            itemData={{ render: Row, rows: displayRows }} itemKey={virtualRowKey}>{VirtualRow}</FixedSizeList>}
        </div>
        {upload.uploads.length ? <section className="explorer-uploads" aria-label="粘贴上传任务">
          <header><span>{uploading ? '正在上传…' : '上传记录'}</span>
            {uploading ? <button onClick={upload.cancel}>取消上传</button> : null}<button onClick={upload.clear}>清除已结束</button>
          </header>
          <ul>{upload.uploads.map((item) => <li key={item.id}>
            <span title={item.path ?? `${item.directory}/${item.file.name}`}>{item.path?.split('/').pop() ?? item.file.name}</span>
            {item.status === 'uploading' ? <progress aria-label={`上传进度 ${item.file.name}`} value={item.loaded} max={Math.max(1, item.file.size)} /> : null}
            <small role="status">{item.status === 'waiting' ? '等待上传' : item.status === 'success' ? '已上传' : item.status === 'error' ? '上传失败' : `${Math.min(100, Math.round(item.loaded / Math.max(1, item.file.size) * 100))}%`}</small>
            {item.status === 'error' ? <button onClick={() => upload.retry(item)}>重试</button> : null}
            {item.error ? <small className="explorer-upload-error">{item.error}</small> : null}
          </li>)}</ul>
        </section> : null}
      </div>
      {!collapsed && contextMenu ? <ExplorerContextMenu
        x={contextMenu.x}
        y={contextMenu.y}
        path={contextMenu.displayPath}
        onOpenFloating={contextMenu.directory ? undefined : () => {
          const node = rows.find(row => row.path === contextMenu.path);
          if (node) withFloatingOpen(() => onOpenFile(node));
        }}
        onClose={() => setContextMenu(undefined)}
        onCopyFileName={() => void copyText(contextMenu.path.split('/').filter(Boolean).pop() ?? '/')}
        onCopyRelativePath={() => void copyText(contextMenu.path.slice(root.replace(/\/+$/, '').length).replace(/^\/+/, '') || '.')}
        onCopySystemPath={() => void copyText(contextMenu.path)}
        onPaste={() => void pasteFromMenu(contextMenu.directory ? contextMenu.path : contextMenu.path.slice(0, contextMenu.path.lastIndexOf('/')) || '/')}
        onDownload={contextMenu.directory ? undefined : () => downloadFile(contextMenu.path)}
        onRename={contextMenu.renameable && onRenameFile ? () => beginRename(contextMenu.path) : undefined}
        onCreateFile={contextMenu.directory && onCreateFile ? () => beginCreation(contextMenu.path, 'file') : undefined}
        onCreateDirectory={contextMenu.directory && onCreateDirectory ? () => beginCreation(contextMenu.path, 'directory') : undefined}
        onDelete={contextMenu.path !== root && onDeleteEntry ? () => onDeleteEntry(contextMenu.path, contextMenu.directory) : undefined}
      /> : null}
    </>;
  if (aowHeader) return <AowPanel className="explorer explorer-section" title={title ?? 'Explorer'} icon={titleIcon}
    collapsed={collapsed} onCollapsedChange={changeCollapsed}
    actions={<AowIconButton title="刷新" aria-label={`刷新 ${title ?? 'Explorer'}`} onClick={() => setRefreshKey(key => key + 1)}><RefreshCw /></AowIconButton>}>
    <div onPaste={paste}>{content}</div>
  </AowPanel>;
  return <section className={`side-view explorer${onCollapsedChange ? ' explorer-section' : ''}${collapsed ? ' collapsed' : ''}`} onPaste={paste}>
    <div className="side-title">
      {onCollapsedChange ? <button className="explorer-section-toggle" type="button" aria-expanded={!collapsed} onClick={() => changeCollapsed(!collapsed)}>
        <ChevronRight className={collapsed ? undefined : 'expanded'} />{titleIcon}<strong>{title ?? (titleCase ? 'Explorer' : 'EXPLORER')}</strong>
      </button> : <strong>{title ?? (titleCase ? 'Explorer' : 'EXPLORER')}</strong>}
      <button className="explorer-refresh" title="刷新" aria-label={`刷新 ${title ?? 'Explorer'}`} onClick={() => setRefreshKey(key => key + 1)}><RefreshCw size={14} /></button>
    </div>{content}
  </section>;
}

import { useEffect, useLayoutEffect, useRef, useState, type MouseEvent as ReactMouseEvent } from 'react';
import { createPortal } from 'react-dom';
import { Clipboard, ClipboardPaste, Download, FilePlus2, FolderPlus, Pencil, Trash2 } from 'lucide-react';
import { WorkspaceMenuLabel } from '../../aow/WorkspaceMenuLabel';

interface Props {
  x: number;
  y: number;
  path: string;
  onClose: () => void;
  onOpenFloating?: () => void;
  onCopyFileName: () => void;
  onCopyRelativePath: () => void;
  onCopySystemPath: () => void;
  onPaste: () => void;
  onDownload?: () => void;
  onRename?: () => void;
  onCreateFile?: () => void;
  onCreateDirectory?: () => void;
  onDelete?: () => void;
}

export function ExplorerContextMenu({ x, y, path, onClose, onCopyFileName, onCopyRelativePath, onCopySystemPath, onPaste, onDownload, onRename, onCreateFile, onCreateDirectory, onDelete, onOpenFloating }: Props) {
  const menu = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x, y });

  useLayoutEffect(() => {
    const bounds = menu.current?.getBoundingClientRect();
    if (!bounds) return;
    setPosition({
      x: Math.max(4, Math.min(x, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(y, window.innerHeight - bounds.height - 4)),
    });
  }, [x, y]);

  useEffect(() => {
    const close = () => onClose();
    const key = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('pointerdown', close);
    window.addEventListener('scroll', close, true);
    window.addEventListener('resize', close);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', close);
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('resize', close);
      window.removeEventListener('keydown', key);
    };
  }, [onClose]);

  const action = (callback: () => void) => (event: ReactMouseEvent) => {
    event.stopPropagation(); callback(); onClose();
  };

  return createPortal(
    <div ref={menu} className="project-aow-context-menu explorer-context-menu" style={{ left: position.x, top: position.y }} role="menu" aria-label={`${path} 操作`} onPointerDown={(event) => event.stopPropagation()}>
      {onOpenFloating ? <button role="menuitem" onClick={action(onOpenFloating)}><WorkspaceMenuLabel action="floating" /></button> : null}
      <button role="menuitem" onClick={action(onCopyFileName)}><Clipboard />复制 • 文件名</button>
      <button role="menuitem" onClick={action(onCopyRelativePath)}><Clipboard />复制 • 相对路径</button>
      <button role="menuitem" onClick={action(onCopySystemPath)}><Clipboard />复制 • 系统路径</button>
      <hr />
      <button role="menuitem" onClick={action(onPaste)}><ClipboardPaste />粘贴 • 文件|截图<kbd>{/Mac|iPhone|iPad/.test(navigator.platform) ? '⌘V' : 'Ctrl+V'}</kbd></button>
      {onCreateFile ? <button role="menuitem" onClick={action(onCreateFile)}><FilePlus2 />新建文件</button> : null}
      {onCreateDirectory ? <button role="menuitem" onClick={action(onCreateDirectory)}><FolderPlus />新建目录</button> : null}
      {onRename ? <button role="menuitem" onClick={action(onRename)}><Pencil />重命名</button> : null}
      {onDownload ? <button role="menuitem" onClick={action(onDownload)}><Download />下载</button> : null}
      {onDelete ? <button className="danger" role="menuitem" onClick={action(onDelete)}><Trash2 />删除</button> : null}
    </div>, document.body);
}

import { Folder, FolderOpen } from 'lucide-react';
import theme from '../../assets/seti/vs-seti-icon-theme.json';
import languages from '../../assets/seti/language-associations.json';
import './file-type-icon.css';

interface Props { path: string; className?: string }
interface DirectoryProps { expanded?: boolean; className?: string }

const fileNames = new Map(Object.entries(theme.fileNames));
const fileExtensions = new Map(Object.entries(theme.fileExtensions));
const languageNames = new Map(Object.entries(languages.fileNames));
const languageExtensions = new Map(Object.entries(languages.fileExtensions));
const languagePatterns = Object.entries(languages.filePatterns)
  .sort(([a], [b]) => b.length - a.length)
  .map(([pattern, icon]) => ({
    pattern: new RegExp(`^${pattern.split('*').map(part => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('.*')}$`),
    icon,
  }));
const icons = new Map(Object.entries(theme.iconDefinitions).map(([id, icon]) => [id, {
  character: String.fromCodePoint(parseInt(icon.fontCharacter.slice(1), 16)),
  color: 'fontColor' in icon ? icon.fontColor : 'var(--aow-muted)',
}]));

function iconForPath(path: string) {
  const name = path.split(/[/\\]/).pop()?.toLowerCase() ?? '';
  const named = fileNames.get(name);
  if (named) return named;

  // VS Code gives named files and compound extensions (e.g. test.tsx)
  // precedence over the language's icon. Only inspect the basename.
  const suffixes: string[] = [];
  for (let dot = name.indexOf('.'); dot >= 0; dot = name.indexOf('.', dot + 1)) {
    const suffix = name.slice(dot + 1);
    const icon = fileExtensions.get(suffix);
    if (icon) return icon;
    suffixes.push(suffix);
  }
  const language = languageNames.get(name) ?? languagePatterns.find(({ pattern }) => pattern.test(name))?.icon;
  if (language) return language;
  for (const suffix of suffixes) {
    const icon = languageExtensions.get(suffix);
    if (icon) return icon;
  }
  return theme.file;
}

export function DirectoryTypeIcon({ expanded = false, className = '' }: DirectoryProps) {
  const Icon = expanded ? FolderOpen : Folder;
  return <Icon aria-hidden="true" className={`directory-type-icon ${className}`.trim()} />;
}

export function FileTypeIcon({ path, className = '' }: Props) {
  const icon = icons.get(iconForPath(path)) ?? icons.get(theme.file)!;
  return <i aria-hidden="true" className={`file-type-icon ${className}`.trim()}
    data-icon={icon.character} style={{ color: icon.color }} />;
}

import { ChevronRight, FileText } from 'lucide-react';
import { filesApi } from './api';
import { DirectoryTypeIcon, FileTypeIcon } from './FileTypeIcon';
import { MarkdownContent } from '../../components/MarkdownContent';
import { MobilePageHeader, MobileRefresh, MobileState } from '../../mobile/MobilePrimitives';
import { useMobileResource, useMobileScroll, type MobileRoute } from '../../mobile/mobileState';
import type { MobileNavigate } from '../../mobile/mobileState';

const basename = (path: string) => path.split('/').filter(Boolean).pop() ?? path;
function within(root: string, path: string) { return path === root || path.startsWith(`${root.replace(/\/$/, '')}/`); }

export function MobileFiles({ route, notesPath, visible, navigate, back }: {
  route: MobileRoute; notesPath: string; visible: boolean; navigate: MobileNavigate; back: () => void;
}) {
  const root = route.notes === '1' ? notesPath : route.workspace;
  const directory = route.directory && (route.fileSource === 'external' || within(root, route.directory)) ? route.directory : root;
  const listing = useMobileResource(`directory.${directory}`, () => filesApi.listDirectory(directory), visible && !route.file);
  const scroll = useMobileScroll(`directory.${directory}`, !!listing.data);
  const base: Partial<MobileRoute> = { workspace: route.workspace, view: 'files', notes: route.notes, fileSource: route.fileSource };
  if (route.file) return <MobileFileReader path={route.file} back={back} />;
  return <section className="mobile-content-page">
    <MobilePageHeader title={directory === root ? (route.notes === '1' ? 'Notes' : '文件') : basename(directory)}
      subtitle={directory === root ? '浏览工作区内容' : directory.slice(root.length + 1)} back={directory === root ? undefined : back}
      actions={<MobileRefresh reload={listing.reload} loading={listing.loading} />} />
    <div className="mobile-segments" role="tablist" aria-label="文件来源">
      <button role="tab" aria-selected={route.notes !== '1'} onClick={() => navigate({ workspace: route.workspace, view: 'files' }, true)}><DirectoryTypeIcon />项目文件</button>
      <button role="tab" aria-selected={route.notes === '1'} onClick={() => navigate({ workspace: route.workspace, view: 'files', notes: '1' }, true)}><FileText size={16} />Notes</button>
    </div>
    <div className="mobile-scroll" ref={scroll}>
      <MobileState loading={listing.loading && !listing.data} error={listing.error} retry={listing.reload} empty={listing.data?.entries.length === 0 ? '这个目录是空的。' : undefined} />
      <div className="mobile-list">{listing.data?.entries.slice().sort((a, b) => Number(b.kind === 'directory') - Number(a.kind === 'directory') || a.name.localeCompare(b.name))
        .map((entry) => <button key={entry.path} className="mobile-list-row" onClick={() => navigate({ ...base, ...(entry.kind === 'directory' ? { directory: entry.path } : { directory, file: entry.path }) })}>
          <div className="mobile-row-icon">{entry.kind === 'directory' ? <DirectoryTypeIcon /> : <FileTypeIcon path={entry.path} />}</div>
          <div className="mobile-row-main"><strong>{entry.name}</strong><span>{entry.kind === 'directory' ? '文件夹' : `${Math.max(1, Math.ceil(entry.size / 1024))} KB`}</span></div><ChevronRight size={17} />
        </button>)}</div>
    </div>
  </section>;
}

function MobileFileReader({ path, back }: { path: string; back: () => void }) {
  const image = /\.(png|jpe?g|gif|webp|svg|avif|ico|bmp)$/i.test(path);
  const pdf = /\.pdf$/i.test(path);
  const markdown = /\.(md|markdown)$/i.test(path);
  const docx = /\.docx$/i.test(path);
  const data = useMobileResource(`file.${path}`, async () => {
    if (image || pdf) return { content: '', html: false };
    if (docx) {
      const [{ default: mammoth }, { default: DOMPurify }, arrayBuffer] = await Promise.all([import('mammoth'), import('dompurify'), filesApi.readBinary(path)]);
      const result = await mammoth.convertToHtml({ arrayBuffer });
      return { content: DOMPurify.sanitize(result.value), html: true };
    }
    return { content: (await filesApi.readText(path)).content, html: false };
  });
  const scroll = useMobileScroll(`file.${path}`, !!data.data);
  return <section className="mobile-content-page">
    <MobilePageHeader title={basename(path)} subtitle="文件预览" back={back} actions={<MobileRefresh reload={data.reload} loading={data.loading} />} />
    <div className="mobile-scroll mobile-file-reader" ref={scroll}>
      <MobileState loading={data.loading && !data.data} error={data.error} retry={data.reload} />
      {image && <img className="mobile-file-image" src={filesApi.rawUrl(path)} alt={basename(path)} />}
      {pdf && <><a className="mobile-button" href={filesApi.rawUrl(path)}>打开 PDF</a><iframe className="mobile-pdf" title={basename(path)} src={filesApi.rawUrl(path)} /></>}
      {data.data && !image && !pdf && (data.data.html ? <div className="mobile-markdown" dangerouslySetInnerHTML={{ __html: data.data.content }} />
        : markdown ? <MarkdownContent text={data.data.content} className="mobile-markdown" /> : <pre className="mobile-code">{data.data.content}</pre>)}
    </div>
  </section>;
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { DragEvent } from 'react';
import { ArrowUp, Check, ChevronDown, ChevronRight, Copy, Download, Home, LoaderCircle, Pin, PinOff, RefreshCw, Upload, X } from 'lucide-react';
import { filesApi } from './api';
import { DirectoryTypeIcon, FileTypeIcon } from './FileTypeIcon';
import type { DirectoryListing, FileEntry } from './types';
import { usePinnedDirectories } from './usePinnedDirectories';
import './system-file-browser.css';

interface UploadItem {
  id: number;
  file: File;
  directory: string;
  loaded: number;
  status: 'waiting' | 'uploading' | 'success' | 'error';
  error?: string;
}

interface DirectoryTreeProps {
  path: string;
  depth?: number;
  currentPath: string;
  listings: Record<string, DirectoryListing>;
  expanded: Set<string>;
  pending: Set<string>;
  errors: Record<string, string>;
  onToggle: (path: string) => void;
  onNavigate: (path: string) => void;
  onRetry: (path: string) => void;
  onCopy: (path: string) => void;
  pins: ReturnType<typeof usePinnedDirectories>;
}

function DirectoryPin({ path, label = path, pins, className = '', showLabel = false }: {
  path: string; label?: string; pins: ReturnType<typeof usePinnedDirectories>; className?: string; showLabel?: boolean;
}) {
  const pinned = pins.paths.includes(path);
  const pending = pins.pending.has(path);
  const action = `${pinned ? '取消 Pin' : 'Pin'} ${label}`;
  return <button type="button" className={`system-file-pin ${className}`} title={action} aria-label={action} aria-pressed={pinned}
    disabled={!path || pins.loading || pending} onClick={() => void pins.toggle(path, pinned)}>
    {pending ? <LoaderCircle className="system-file-spin" /> : pinned ? <PinOff /> : <Pin />}{showLabel ? <span>{pinned ? '取消 Pin' : 'Pin 当前目录'}</span> : null}
  </button>;
}

const errorMessage = (reason: unknown) => reason instanceof Error ? reason.message : String(reason);
const parentPath = (path: string) => path.slice(0, path.lastIndexOf('/')) || '/';

function ancestors(path: string) {
  const paths = [path];
  while (path !== '/') { path = parentPath(path); paths.unshift(path); }
  return paths;
}

function formatSize(size: number) {
  if (size < 1024) return `${size} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let unit = -1;
  do { size /= 1024; unit += 1; } while (size >= 1024 && unit < units.length - 1);
  return `${size.toFixed(size < 10 ? 1 : 0)} ${units[unit]}`;
}

function DirectoryTree(props: DirectoryTreeProps) {
  const { path, depth = 0, currentPath, listings, expanded, pending, errors, onToggle, onNavigate, onRetry, onCopy, pins } = props;
  const isExpanded = expanded.has(path);
  const directories = listings[path]?.entries.filter((entry) => entry.kind === 'directory');
  return <li>
    <div className={`system-file-tree-row${currentPath === path ? ' selected' : ''}`}>
      <button className="system-file-tree-toggle" style={{ marginLeft: depth * 13 }} aria-label={`${isExpanded ? '折叠' : '展开'} ${path}`} aria-expanded={isExpanded} onClick={() => onToggle(path)}>
        {pending.has(path) ? <LoaderCircle className="system-file-spin" /> : isExpanded ? <ChevronDown /> : <ChevronRight />}
      </button>
      <button className="system-file-tree-name" title={path} aria-current={currentPath === path ? 'location' : undefined} onClick={() => onNavigate(path)}>
        <DirectoryTypeIcon expanded={isExpanded} /><span>{path === '/' ? '/' : path.split('/').pop()}</span>
      </button>
      <span className="system-file-tree-actions">
        <DirectoryPin path={path} pins={pins} className="system-file-tree-pin" />
        <button className="system-file-tree-copy" title={`复制路径 ${path}`} aria-label={`复制路径 ${path}`} onClick={() => onCopy(path)}><Copy /></button>
      </span>
    </div>
    {isExpanded ? <ul>
      {errors[path] ? <li className="system-file-tree-error" style={{ paddingLeft: (depth + 1) * 13 + 8 }} title={errors[path]}>{errors[path]}<button onClick={() => onRetry(path)}>重试</button></li> : null}
      {directories?.map((entry) => <DirectoryTree key={entry.path} {...props} path={entry.path} depth={depth + 1} />)}
      {!pending.has(path) && !errors[path] && directories?.length === 0 ? <li className="system-file-tree-empty" style={{ paddingLeft: (depth + 1) * 13 + 8 }}>无子目录</li> : null}
    </ul> : null}
  </li>;
}

export function SystemFileBrowser({ open, onHide, onOpenFile, navigationRequest, onPathChange }: { open: boolean; onHide: () => void; onOpenFile: (entry: FileEntry) => void; navigationRequest?: { path: string }; onPathChange?: (path: string) => void }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const fileListRef = useRef<HTMLDivElement>(null);
  const treeRef = useRef<HTMLElement>(null);
  const revealPathRef = useRef('');
  const cacheRef = useRef<Record<string, DirectoryListing>>({});
  const requestsRef = useRef(new Map<string, Promise<DirectoryListing>>());
  const navigationRef = useRef(0);
  const queueRef = useRef<UploadItem[]>([]);
  const uploadingRef = useRef(false);
  const uploadIdRef = useRef(0);
  const dragDepthRef = useRef(0);
  const [home, setHome] = useState('');
  const [currentPath, setCurrentPath] = useState('');
  const [address, setAddress] = useState('');
  const [listings, setListings] = useState<Record<string, DirectoryListing>>({});
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set(['/']));
  const [pending, setPending] = useState<Set<string>>(() => new Set());
  const [directoryErrors, setDirectoryErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [selectedPath, setSelectedPath] = useState('');
  const [dragging, setDragging] = useState(false);
  const [uploads, setUploads] = useState<UploadItem[]>([]);
  const [revealRequest, setRevealRequest] = useState(0);
  const pins = usePinnedDirectories();

  const saveListing = useCallback((path: string, listing: DirectoryListing) => {
    cacheRef.current = { ...cacheRef.current, [path]: listing };
    setListings(cacheRef.current);
  }, []);

  const loadDirectory = useCallback(async (path: string, refresh = false): Promise<DirectoryListing> => {
    const pendingRequest = requestsRef.current.get(path);
    if (pendingRequest) {
      if (!refresh) return pendingRequest;
      await pendingRequest.catch(() => undefined);
    }
    if (!refresh && cacheRef.current[path]) return cacheRef.current[path];
    setPending((previous) => new Set(previous).add(path));
    setDirectoryErrors((previous) => ({ ...previous, [path]: '' }));
    const request: Promise<DirectoryListing> = filesApi.listDirectory(path).then((listing) => {
      if (requestsRef.current.get(path) === request) saveListing(path, listing);
      return listing;
    }).catch((reason: unknown) => {
      if (requestsRef.current.get(path) === request) setDirectoryErrors((previous) => ({ ...previous, [path]: errorMessage(reason) }));
      throw reason;
    }).finally(() => {
      if (requestsRef.current.get(path) !== request) return;
      requestsRef.current.delete(path);
      setPending((previous) => { const next = new Set(previous); next.delete(path); return next; });
    });
    requestsRef.current.set(path, request);
    return request;
  }, [saveListing]);

  const navigate = useCallback(async (path: string, refresh = false) => {
    const generation = ++navigationRef.current;
    setLoading(true);
    setError('');
    setNotice('');
    try {
      const listing = await loadDirectory(path, refresh);
      if (generation !== navigationRef.current) return;
      setCurrentPath(listing.path);
      revealPathRef.current = listing.path;
      setRevealRequest((value) => value + 1);
      setAddress(listing.path);
      setSelectedPath((previous) => listing.entries.some((entry) => entry.path === previous) ? previous : '');
      if (fileListRef.current && listing.path !== currentPath) fileListRef.current.scrollTop = 0;
    } catch (reason) {
      if (generation === navigationRef.current) setError(`无法打开 ${path}：${errorMessage(reason)}`);
    } finally {
      if (generation === navigationRef.current) setLoading(false);
    }
  }, [currentPath, loadDirectory]);

  const loadHome = useCallback(async () => {
    const generation = ++navigationRef.current;
    setLoading(true);
    setError('');
    setNotice('');
    try {
      const listing = await filesApi.listHomeDirectory();
      setHome(listing.path);
      saveListing(listing.path, listing);
      if (generation !== navigationRef.current) return;
      setCurrentPath(listing.path);
      revealPathRef.current = listing.path;
      setRevealRequest((value) => value + 1);
      setAddress(listing.path);
      setSelectedPath('');
    } catch (reason) {
      if (generation === navigationRef.current) setError(`无法打开 Home：${errorMessage(reason)}`);
    } finally {
      if (generation === navigationRef.current) setLoading(false);
    }
  }, [saveListing]);

  // Mounted on first use and kept alive when hidden, including DOM scroll positions and uploads.
  useEffect(() => {
    if (!navigationRequest) void loadHome();
    return () => { navigationRef.current += 1; };
  }, [loadHome]);

  const navigateRef = useRef(navigate);
  navigateRef.current = navigate;
  useEffect(() => { if (navigationRequest) void navigateRef.current(navigationRequest.path); }, [navigationRequest]);
  useEffect(() => { if (currentPath) onPathChange?.(currentPath); }, [currentPath, onPathChange]);

  useEffect(() => {
    dragDepthRef.current = 0;
    setDragging(false);
  }, [open]);

  useEffect(() => {
    if (!currentPath) return;
    const paths = ancestors(currentPath);
    setExpanded((previous) => new Set([...previous, ...paths]));
    paths.forEach((path) => { void loadDirectory(path).catch(() => undefined); });
  }, [currentPath, loadDirectory, revealRequest]);

  useLayoutEffect(() => {
    const tree = treeRef.current;
    if (!open || !tree || !currentPath || revealPathRef.current !== currentPath) return;
    const name = tree.querySelector('[aria-current="location"]');
    const row = name?.parentElement;
    if (!name || !row) return;
    const bounds = tree.getBoundingClientRect();
    const rowBounds = row.getBoundingClientRect();
    const headingHeight = tree.querySelector('.system-file-pane-title')?.clientHeight ?? 0;
    if (rowBounds.top < bounds.top + headingHeight) tree.scrollTop += rowBounds.top - bounds.top - headingHeight;
    else if (rowBounds.bottom > bounds.bottom) tree.scrollTop += rowBounds.bottom - bounds.bottom;
    const nameStart = row.querySelector('.system-file-tree-toggle')?.getBoundingClientRect().left ?? name.getBoundingClientRect().left;
    const nameEnd = name.querySelector('span')?.getBoundingClientRect().right ?? nameStart;
    const visibleLeft = bounds.left + 5;
    const actionsWidth = row.querySelector('.system-file-tree-actions')?.clientWidth ?? 0;
    const visibleRight = bounds.left + tree.clientWidth - 5 - actionsWidth;
    if (nameStart < visibleLeft || nameEnd > visibleRight) {
      tree.scrollLeft += nameStart < visibleLeft || nameEnd - nameStart > visibleRight - visibleLeft
        ? nameStart - visibleLeft : nameEnd - visibleRight;
    }
    revealPathRef.current = '';
  }, [open, currentPath, listings, expanded, revealRequest]);

  const toggleDirectory = (path: string) => {
    const opening = !expanded.has(path);
    setExpanded((previous) => {
      const next = new Set(previous);
      if (opening) next.add(path); else next.delete(path);
      return next;
    });
    if (opening) void loadDirectory(path).catch(() => undefined);
  };

  const copyPath = async (path: string) => {
    setNotice('');
    try {
      try {
        if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable');
        await navigator.clipboard.writeText(path);
      } catch {
        const focused = document.activeElement;
        const input = document.createElement('textarea');
        input.value = path;
        input.readOnly = true;
        input.style.cssText = 'position:fixed;opacity:0;pointer-events:none';
        dialogRef.current!.appendChild(input);
        try {
          input.select();
          if (!document.execCommand('copy')) throw new Error('浏览器拒绝复制操作');
        } finally {
          input.remove();
          if (focused instanceof HTMLElement) focused.focus({ preventScroll: true });
        }
      }
      setNotice(`已复制：${path}`);
    } catch (reason) { setError(`复制失败：${errorMessage(reason)}`); }
  };

  const enqueueUploads = (files: File[]) => {
    if (!currentPath || loading || files.length === 0) return;
    const items: UploadItem[] = files.map((file) => ({ id: ++uploadIdRef.current, file, directory: currentPath, loaded: 0, status: 'waiting' }));
    queueRef.current.push(...items);
    setUploads((previous) => [...previous, ...items]);
    if (uploadingRef.current) return;
    uploadingRef.current = true;
    const update = (id: number, changes: Partial<UploadItem>) => setUploads((previous) => previous.map((item) => item.id === id ? { ...item, ...changes } : item));
    void (async () => {
      try {
        while (queueRef.current.length) {
          const item = queueRef.current.shift()!;
          update(item.id, { status: 'uploading' });
          try {
            await filesApi.uploadFile(item.directory, item.file, (loaded) => update(item.id, { loaded }));
            update(item.id, { status: 'success', loaded: item.file.size });
            try { await loadDirectory(item.directory, true); }
            catch (reason) { setError(`文件已上传，但目录刷新失败：${errorMessage(reason)}`); }
          } catch (reason) { update(item.id, { status: 'error', error: errorMessage(reason) }); }
        }
      } finally { uploadingRef.current = false; }
    })();
  };

  const dropFiles = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    dragDepthRef.current = 0;
    setDragging(false);
    const items = [...event.dataTransfer.items];
    const containsDirectory = items.some((item) => item.webkitGetAsEntry?.()?.isDirectory);
    if (containsDirectory) setError('请拖入文件；暂不支持整目录上传。');
    const files = items.length
      ? items.filter((item) => item.kind === 'file' && !item.webkitGetAsEntry?.()?.isDirectory).map((item) => item.getAsFile()).filter((file): file is File => file !== null)
      : [...event.dataTransfer.files];
    enqueueUploads(files);
  };

  const listing = listings[currentPath];
  const activeUploads = uploads.filter((item) => item.status === 'waiting' || item.status === 'uploading').length;

  return <div ref={dialogRef} className="system-file-browser" hidden={!open} role="region" aria-label="系统文件浏览器"

    onKeyDown={(event) => { event.stopPropagation(); if (event.key === 'Escape') { event.preventDefault(); onHide(); } }}
    onClick={(event) => {
      if (event.target !== event.currentTarget) return;
      const rect = event.currentTarget.getBoundingClientRect();
      if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) onHide();
    }}
    onDragEnter={(event) => {
      if (!event.dataTransfer.types.includes('Files')) return;
      event.preventDefault(); event.stopPropagation();
      dragDepthRef.current += 1;
      setDragging(true);
    }}
    onDragOver={(event) => {
      if (!event.dataTransfer.types.includes('Files')) return;
      event.preventDefault(); event.stopPropagation();
      event.dataTransfer.dropEffect = currentPath && !loading ? 'copy' : 'none';
    }}
    onDragLeave={(event) => {
      event.preventDefault(); event.stopPropagation();
      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
      if (!dragDepthRef.current) setDragging(false);
    }}
    onDrop={dropFiles}
  >
    <div className="system-file-toolbar">
      <div className="system-file-toolbar-actions">
        <button title="上级目录" aria-label="上级目录" disabled={!currentPath || currentPath === '/'} onClick={() => void navigate(parentPath(currentPath))}><ArrowUp /></button>
        <button title="刷新当前目录" aria-label="刷新当前目录" disabled={loading} onClick={() => void (currentPath ? navigate(currentPath, true) : loadHome())}><RefreshCw className={loading ? 'system-file-spin' : ''} /></button>
        <DirectoryPin path={currentPath} label="当前目录" pins={pins} showLabel />
        <button className="system-file-upload-button" disabled={!currentPath || loading} onClick={() => fileInputRef.current?.click()}><Upload />上传文件</button>
        <input ref={fileInputRef} type="file" multiple hidden aria-label="选择上传文件" onChange={(event) => { enqueueUploads([...event.currentTarget.files ?? []]); event.currentTarget.value = ''; }} />
      </div>
    </div>
    <form className="system-file-address" onSubmit={(event) => {
      event.preventDefault();
      let path = address.trim();
      if (home && (path === '~' || path.startsWith('~/'))) path = home + path.slice(1);
      if (!path.startsWith('/')) { setError('请输入绝对路径，例如 /tmp 或 ~/Documents'); return; }
      void navigate(path.replace(/\/{2,}/g, '/').replace(/\/$/, '') || '/');
    }}><input autoFocus aria-label="目录路径" spellCheck={false} value={address} placeholder="输入目录路径" onChange={(event) => setAddress(event.target.value)} /><button type="submit">前往</button><button type="button" title="复制当前目录路径" aria-label="复制当前目录路径" disabled={!currentPath} onClick={() => void copyPath(currentPath)}><Copy /></button></form>
    {error ? <div className="system-file-error" role="alert"><span>{error}</span><button aria-label="关闭错误提示" onClick={() => setError('')}><X /></button></div> : null}
    <div className="system-file-body">
      <aside className="system-file-shortcuts" aria-label="快捷导航与收藏">
        <div className="system-file-pane-title">快捷导航</div>
        <nav aria-label="快捷导航">
          <button title="根目录 /" onClick={() => void navigate('/')} aria-pressed={currentPath === '/'}><DirectoryTypeIcon /><span>/</span></button>
          <button title="/tmp" onClick={() => void navigate('/tmp')} aria-pressed={currentPath === '/tmp'}><DirectoryTypeIcon /><span>/tmp</span></button>
          <button title={home || 'Home'} onClick={() => void (home ? navigate(home) : loadHome())} aria-pressed={!!home && currentPath === home}><Home /><span>Home</span></button>
        </nav>
        <section className="system-file-bookmarks" aria-label="收藏目录">
          <div className="system-file-pane-title"><Pin /><span>收藏 / Pin</span><button title="刷新收藏" aria-label="刷新收藏" disabled={pins.loading} onClick={() => void pins.reload()}><RefreshCw className={pins.loading ? 'system-file-spin' : ''} /></button></div>
          {pins.error ? <div className="system-file-bookmark-error" role="alert"><span>{pins.error}</span><button onClick={() => void pins.reload()}>重新加载</button></div> : null}
          {pins.loading && pins.paths.length === 0 ? <p className="system-file-bookmarks-empty">正在加载收藏…</p> : !pins.error && pins.paths.length === 0 ? <p className="system-file-bookmarks-empty">Pin 常用目录，在这里快速访问。</p> : null}
          <ul>{pins.paths.map((path) => <li key={path} className={currentPath === path ? 'selected' : ''}>
            <button className="system-file-bookmark-link" title={path} aria-label={`打开收藏 ${path}`} aria-current={currentPath === path ? 'location' : undefined} onClick={() => void navigate(path)}><DirectoryTypeIcon /><span><strong>{path.split('/').pop() || '/'}</strong><small>{path}</small></span></button>
            <DirectoryPin path={path} pins={pins} />
          </li>)}</ul>
        </section>
      </aside>
      <aside className="system-file-tree" ref={treeRef} aria-label="目录树"><div className="system-file-pane-title">目录树</div><ul><DirectoryTree path="/" currentPath={currentPath} listings={listings} expanded={expanded} pending={pending} errors={directoryErrors} onToggle={toggleDirectory} onNavigate={(path) => void navigate(path)} onRetry={(path) => { void loadDirectory(path, true).catch(() => undefined); }} onCopy={(path) => void copyPath(path)} pins={pins} /></ul></aside>
      <div className="system-file-list" ref={fileListRef} aria-label="文件列表" aria-busy={loading}>
        <table><thead><tr><th>名称</th><th>大小</th><th>修改时间</th><th>操作</th></tr></thead><tbody>
          {listing?.entries.map((entry) => <tr key={entry.path} className={selectedPath === entry.path ? 'selected' : ''} aria-selected={selectedPath === entry.path} onClick={() => setSelectedPath(entry.path)} onDoubleClick={() => { if (entry.kind === 'directory') void navigate(entry.path); }}>
            <td><button className="system-file-entry-name" title={entry.is_symlink ? `${entry.path} → ${entry.link_target}` : entry.path} onClick={() => { setSelectedPath(entry.path); if (entry.kind === 'directory') void navigate(entry.path); }}>
              {entry.kind === 'directory' ? <DirectoryTypeIcon /> : <FileTypeIcon path={entry.path} />}<span>{entry.name}</span>{entry.is_symlink ? <small>↗</small> : null}
            </button></td>
            <td>{entry.kind === 'file' ? formatSize(entry.size) : '—'}</td>
            <td>{entry.modified_ms == null ? '—' : new Date(entry.modified_ms).toLocaleString()}</td>
            <td><div className="system-file-entry-actions">{entry.kind === 'file' && !/\.(png|jpe?g|gif|webp|ico|bmp|pdf|zip|gz|tar|exe|so|woff2?|mp[34]|mov|docx?|xlsx?)$/i.test(entry.name) ? <button title="打开文件" aria-label={`打开 ${entry.name}`} onClick={() => onOpenFile(entry)}>打开</button> : null}<button title="复制路径" aria-label={`复制路径 ${entry.name}`} onClick={() => void copyPath(entry.path)}><Copy /></button>{entry.kind === 'directory' ? <DirectoryPin path={entry.path} label={entry.name} pins={pins} /> : entry.kind === 'file' ? <a href={filesApi.rawUrl(entry.path)} download={entry.name} title="下载文件" aria-label={`下载 ${entry.name}`}><Download /></a> : null}</div></td>
          </tr>)}
        </tbody></table>
        {!listing ? <div className="system-file-empty">{loading ? <><LoaderCircle className="system-file-spin" />正在加载目录…</> : '请选择目录'}</div> : listing.entries.length === 0 ? <div className="system-file-empty"><DirectoryTypeIcon expanded />目录为空，可拖入文件上传</div> : null}
      </div>
    </div>
    {uploads.length > 0 ? <section className="system-file-uploads" aria-label="上传任务">
      <header><strong>{activeUploads ? `正在上传 · ${activeUploads} 个文件` : '上传记录'}</strong><span>隐藏窗口后继续上传</span><button onClick={() => setUploads((previous) => previous.filter((item) => item.status === 'waiting' || item.status === 'uploading'))}>清除已结束</button></header>
      <ul>{uploads.map((item) => <li key={item.id}>
        {item.status === 'success' ? <Check className="system-file-success" /> : item.status === 'error' ? <X className="system-file-failure" /> : <LoaderCircle className={item.status === 'uploading' ? 'system-file-spin' : ''} />}
        <div title={`${item.directory.replace(/\/$/, '')}/${item.file.name}`}><strong>{item.file.name}</strong><small>{item.directory}</small></div>
        {item.status === 'uploading' ? <progress aria-label={`上传进度 ${item.file.name}`} max={item.file.size || 1} value={item.loaded} /> : null}
        <span className={item.status === 'error' ? 'system-file-failure' : ''} title={item.error}>{item.status === 'waiting' ? '等待上传' : item.status === 'success' ? '已上传' : item.status === 'error' ? item.error : item.loaded >= item.file.size ? '正在保存…' : `${Math.round(item.loaded / (item.file.size || 1) * 100)}%`}</span>
      </li>)}</ul>
    </section> : null}
    <footer className="system-file-footer"><span role="status" title={notice || currentPath}>{notice || (loading ? '正在加载…' : `${listing?.entries.length ?? 0} 个项目 · ${currentPath}`)}</span><span>拖入文件上传到当前目录</span></footer>
    {dragging ? <div className="system-file-drop-overlay"><Upload /><strong>{loading || !currentPath ? '请等待目录加载完成' : '松开以上传文件'}</strong><span>{currentPath}</span></div> : null}
  </div>;
}

import type { DirectoryListing, TextFile, PinnedDirectories } from './types';
import { fetchWithTimeout, HttpRequestError, request } from '../../lib/http';
import { aowRequest } from '../../lib/aowRequest';
import { appUrl } from '../../lib/basePath';

const encodePath = (path: string) => path.split('/').map(encodeURIComponent).join('/');

async function ensureFile(path: string) {
  // The raw-file endpoint validates that the target is a readable regular
  // file.  Cancel the body immediately so this remains a metadata check.
  const response = await fetchWithTimeout(`/api/fs/raw${encodePath(path)}`, {
    cache: 'no-store',
  });
  if (!response.ok) {
    const payload = await response.json().catch(() => null);
    throw new HttpRequestError(payload?.message ?? payload?.error?.message ?? `HTTP ${response.status}`);
  }
  await response.body?.cancel();
}

export const filesApi = {
  // `/api/fs/tree` is the root-directory route.  Keeping the root request
  // free of a trailing slash avoids falling through to the SPA route.
  listDirectory: (path: string) => request<DirectoryListing>(path === '/' ? '/api/fs/tree' : `/api/fs/tree${encodePath(path)}`),
  listHomeDirectory: () => request<DirectoryListing>('/api/fs/home'),
  ensureFile,
  readText: (path: string, signal?: AbortSignal) => request<TextFile>(`/api/fs/text${encodePath(path)}`, { cache: 'no-store', signal }),
  rawUrl: (path: string) => appUrl(`/api/fs/raw${encodePath(path)}`),
  readBlob: async (path: string, signal?: AbortSignal) => {
    const response = await fetchWithTimeout(`/api/fs/raw${encodePath(path)}`, { cache: 'no-store', signal }, 30_000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.blob();
  },
  readBinary: async (path: string) => {
    const response = await fetchWithTimeout(`/api/fs/raw${encodePath(path)}`, { cache: 'no-store' }, 30_000);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.arrayBuffer();
  },
  saveText: async (path: string, content: string, version?: string) => {
    const response = await fetchWithTimeout(`/api/fs/file${encodePath(path)}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        ...(version ? { 'If-Match': `"${version}"` } : {}),
      },
      body: content,
    }, 20_000);
    const payload = await response.json().catch(() => null);
    if (!response.ok) throw new Error(payload?.message ?? `HTTP ${response.status}`);
    return payload as { path: string; size: number; created: boolean; version: string };
  },
  createEntry: (parent: string, name: string, kind: 'file' | 'directory') => request<{ path: string; name: string; kind: 'file' | 'directory' }>('/api/fs/entries', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ parent, name, kind }),
  }, 0),
  renameEntry: (path: string, name: string) => request<{ path: string; name: string }>('/api/fs/entries', {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, name }),
  }, 0),
  deleteEntry: (path: string) => request<void>(`/api/fs/entries?${new URLSearchParams({ path })}`, { method: 'DELETE' }, 0),
  uploadFile: (directory: string, file: File, onProgress?: (loaded: number) => void, options?: { keepBoth?: boolean; signal?: AbortSignal }) => {
    const path = `${directory.replace(/\/$/, '')}/${file.name}`;
    return new Promise<{ path: string; size: number; created: boolean; version: string }>((resolve, reject) => {
      const request = new XMLHttpRequest();
      request.open('PUT', appUrl(`/api/fs/file${encodePath(path)}${options?.keepBoth ? '?keep_both=true' : ''}`));
      request.setRequestHeader('Content-Type', file.type || 'application/octet-stream');
      request.responseType = 'json';
      request.timeout = 120_000;
      request.upload.onprogress = (event) => onProgress?.(event.loaded);
      request.onload = () => {
        if (request.status >= 200 && request.status < 300) resolve(request.response);
        else reject(new Error(request.response?.message ?? `HTTP ${request.status}`));
      };
      request.onerror = () => reject(new Error('上传失败，请检查网络连接'));
      request.ontimeout = () => reject(new Error('上传超时（120 秒）'));
      request.onabort = () => reject(new Error('上传已取消'));
      const abort = () => request.abort();
      request.onloadend = () => options?.signal?.removeEventListener('abort', abort);
      if (options?.signal?.aborted) { reject(new Error('上传已取消')); return; }
      options?.signal?.addEventListener('abort', abort, { once: true });
      request.send(file);
    });
  },
  pinnedDirectories: () => aowRequest<PinnedDirectories>('/api/aow/pinned-directories', { cache: 'no-store' }),
  updatePinnedDirectories: (input: { add?: string[]; remove?: string[] }) => aowRequest<PinnedDirectories>('/api/aow/pinned-directories', {
    method: 'PATCH', body: JSON.stringify(input),
  }),
};

const imageExtensions: Record<string, string> = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp',
  'image/bmp': 'bmp', 'image/tiff': 'tiff', 'image/avif': 'avif', 'image/svg+xml': 'svg',
};

function screenshotFile(blob: Blob): File {
  const extension = imageExtensions[blob.type.toLowerCase()];
  if (!extension) throw new Error(`暂不支持此剪贴板图片格式：${blob.type}`);
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').replace(/\.\d+Z$/, '');
  return new File([blob], `screenshot-${stamp}.${extension}`, { type: blob.type });
}

export function pastedFiles(data: DataTransfer): { files: File[]; hasDirectories: boolean } {
  const items = Array.from(data.items);
  const hasDirectories = items.some((item) => item.kind === 'file' && item.webkitGetAsEntry?.()?.isDirectory);
  const files = items.length
    ? items.filter((item) => item.kind === 'file' && !item.webkitGetAsEntry?.()?.isDirectory)
      .map((item) => item.getAsFile()).filter((file): file is File => file !== null)
    : Array.from(data.files);
  return {
    // Browsers generally name a screenshot "image.png". Preserve all other
    // file names, including text files (which differ from copied plain text).
    files: files.map((file) => imageExtensions[file.type.toLowerCase()] && (!file.name || /^image\.(png|jpe?g|gif|webp)$/i.test(file.name))
      ? screenshotFile(file) : file),
    hasDirectories,
  };
}

export async function readClipboardImages(): Promise<File[]> {
  // Call read immediately from the click handler, before other asynchronous
  // work can consume the browser's transient user activation.
  const items = await navigator.clipboard.read();
  const files: File[] = [];
  for (const item of items) {
    // One clipboard item can expose several representations of one image.
    const type = item.types.find((type) => type === 'image/png')
      ?? item.types.find((type) => imageExtensions[type.toLowerCase()]);
    if (type) files.push(screenshotFile(await item.getType(type)));
  }
  return files;
}

export function isEditableTarget(target: EventTarget | null): boolean {
  return target instanceof HTMLElement && Boolean(target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])'));
}

