function reviewQuery(repo: string, target?: ReviewIdentity) {
  return new URLSearchParams({ repo, ...(target?.provider ? { provider: target.provider } : {}), ...(target?.remote ? { remote: target.remote } : {}) });
}

// A paginated provider call can run for 60 seconds on the server. Do not retry
// scripts automatically: the adapter owns the implementation of its API.
function reviewRequest<T>(url: string) { return request<T>(url, undefined, 0, 65_000); }

export const prApi = {
  reviewTargets: (repo: string) => reviewRequest<ReviewTarget[]>('/api/review-targets?repo=' + encodeURIComponent(repo)),
  myPullRequests: (repo: string, target?: ReviewIdentity) => reviewRequest<MyPullRequests>('/api/my-pull-requests?' + reviewQuery(repo, target)),
  myPullRequest: (repo: string, number: number, target?: ReviewIdentity) => reviewRequest<PullRequestDetail>('/api/my-pull-requests/' + number + '?' + reviewQuery(repo, target)),
  myPullRequestDiff: (repo: string, number: number, path: string, patchOnly = false, target?: ReviewIdentity) => reviewRequest<PullRequestDiff>('/api/my-pull-requests/' + number + '/diff?' + new URLSearchParams({ ...Object.fromEntries(reviewQuery(repo, target)), path, ...(patchOnly ? { patch_only: 'true' } : {}) })),
  reviewProviders: () => aowRequest<ReviewProviderSettings>('/api/aow/review-providers'),
  saveReviewProviders: (settings: ReviewProviderSettings) => aowRequest<ReviewProviderSettings>('/api/aow/review-providers', { method: 'PUT', body: JSON.stringify(settings) }),
  testReviewProvider: (provider: ReviewProvider) => aowRequest<{ operations: string[] }>('/api/aow/review-providers/test', { method: 'POST', body: JSON.stringify(provider) }),
};

export interface PullRequestDiffLine {
  kind: 'hunk' | 'added' | 'removed' | 'context' | 'meta';
  text: string;
  oldLine?: number;
  newLine?: number;
}

// Preserve hunk offsets: additions/deletions consume only their own side's line number.
export function pullRequestDiffLines(patch: string): PullRequestDiffLine[] {
  let oldLine = 0;
  let newLine = 0;
  let inHunk = false;
  const lines = patch.split('\n');
  if (lines.at(-1) === '') lines.pop();
  return lines.map((line) => {
    const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
    if (hunk) {
      oldLine = Number(hunk[1]); newLine = Number(hunk[2]); inHunk = true;
      return { kind: 'hunk', text: line };
    }
    if (inHunk && line.startsWith('+')) return { kind: 'added', text: line.slice(1), newLine: newLine++ };
    if (inHunk && line.startsWith('-')) return { kind: 'removed', text: line.slice(1), oldLine: oldLine++ };
    if (inHunk && line.startsWith(' ')) return { kind: 'context', text: line.slice(1), oldLine: oldLine++, newLine: newLine++ };
    return { kind: 'meta', text: line };
  });
}

export function parsePullRequestNumber(value?: string): number | undefined {
  if (!value || !/^\d+$/.test(value)) return undefined;
  const number = Number(value);
  return Number.isSafeInteger(number) && number > 0 ? number : undefined;
}

export function stateClass(value: string): 'passed' | 'failed' | 'pending' | 'neutral' {
  const state = value.toLowerCase();
  if (['passed', 'succeeded', 'success', 'approved', 'all_passed', 'resolved'].includes(state)) return 'passed';
  if (['failed', 'failure', 'disapproved', 'some_failed', 'timed_out', 'canceled', 'cancelled', 'operation_required', 'action_required', 'startup_failure', 'changes_requested', 'error', 'rejected'].includes(state)) return 'failed';
  if (['pending', 'running', 'in_progress', 'queued', 'warning', 'not_passed', 'unreviewed', 'review_required', 'expected'].includes(state)) return 'pending';
  return 'neutral';
}

export function stateLabel(value: string): string {
  const labels: Record<string, string> = {
    open: '进行中', closed: '已关闭', merged: '已合并', draft: '草稿',
    passed: '已通过', succeeded: '已通过', success: '已通过', approved: '已通过', all_passed: '全部通过',
    failed: '未通过', failure: '未通过', disapproved: '请求修改', rejected: '请求修改', some_failed: '部分未通过',
    pending: '等待中', running: '运行中', in_progress: '运行中', queued: '排队中',
    warning: '有警告', not_passed: '待通过', unreviewed: '待审阅',
    timed_out: '已超时', canceled: '已取消', cancelled: '已取消', operation_required: '需要处理',
    completed: '已完成', skipped: '已跳过', neutral: '无结论', no_checks: '暂无检查',
    changes_requested: '请求修改', review_required: '待审阅', action_required: '需要处理', startup_failure: '启动失败', error: '错误', expected: '等待中', comment: '一般讨论',
    unknown: '状态未知', resolved: '已解决',
  };
  return labels[value.toLowerCase()] || value || '状态未知';
}

export function safeExternalUrl(value?: string | null): string | undefined {
  if (!value) return undefined;
  try {
    const url = new URL(value);
    return ['https:', 'http:'].includes(url.protocol) ? url.href : undefined;
  } catch { return undefined; }
}

export function formatPrTime(value?: string | null): string {
  if (!value) return '未提供';
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return '未提供';
  return new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(date);
}

export function mergeCheckLabel(name: string): string {
  const labels: Record<string, string> = {
    merge_state: '合并状态',
    checkNoConflict: '分支无冲突', checkReviewPassed: '代码审阅', checkCheckRun: 'CI 检查',
    checkCheckRuns: 'CI 检查', checkCheckRunPassed: 'CI 检查', checkAllThreadsResolved: '讨论已解决',
    checkNoUnresolvedThreads: '讨论已解决', checkNotDraft: '已准备好审阅',
    checkSourceBranchExists: '源分支可用', checkTargetBranchExists: '目标分支可用',
    checkFastForward: '可快进合并', checkPullRequestOpen: 'PR 处于开启状态',
  };
  return labels[name] || name;
}

import { useEffect, useState } from 'react';
import { prApi } from './api';
import type { ReviewTarget } from './types';

// Remember the selected remote per repository; never reuse a choice for another
// repository, or silently redirect a saved PR to a different provider.
export function useReviewTarget(repository: string, visible: boolean) {
  const [state, setState] = useState<{ repository: string; targets: ReviewTarget[]; remote: string; error?: string }>();
  const [revision, setRevision] = useState(0);
  useEffect(() => {
    const update = () => setRevision(value => value + 1);
    window.addEventListener('aow-review-providers-changed', update);
    return () => window.removeEventListener('aow-review-providers-changed', update);
  }, []);
  useEffect(() => {
    if (!visible) return;
    let active = true;
    setState(undefined);
    void prApi.reviewTargets(repository).then(targets => {
      if (!active) return;
      let saved = '';
      try { saved = localStorage.getItem('aow-review-remote:' + repository) ?? ''; } catch { /* Storage can be unavailable. */ }
      const unique = new Set(targets.map(t => `${t.provider}:${t.host}/${t.repository}`));
      const remote = targets.some(t => t.remote === saved) ? saved : unique.size === 1 ? targets[0].remote : '';
      setState({ repository, targets, remote });
    }).catch((reason: unknown) => {
      if (active) setState({ repository, targets: [], remote: '', error: reason instanceof Error ? reason.message : String(reason) });
    });
    return () => { active = false; };
  }, [repository, visible, revision]);
  const current = state?.repository === repository ? state : undefined;
  const select = (remote: string) => {
    try { localStorage.setItem('aow-review-remote:' + repository, remote); } catch { /* Optional persistence. */ }
    setState(value => value ? { ...value, remote } : value);
  };
  const target = current?.targets.find(t => t.remote === current.remote);
  return { targets: current?.targets ?? [], remote: current?.remote ?? '', target, select,
    ready: !!current && !current.error && (current.targets.length === 0 || !!target),
    error: current?.error ?? (current?.targets.length && !target ? '请选择要查询的 remote。' : ''),
    reload: () => setRevision(value => value + 1) };
}

