.project-aow-agent-row strong { overflow:hidden; font-size:11px; font-weight:600; text-overflow:ellipsis; white-space:nowrap; }
.project-aow-agent-row code { overflow:hidden; color:var(--aow-muted); font-size:10px; text-overflow:ellipsis; white-space:nowrap; }
.project-aow-agent-row small { color:var(--aow-muted); font-size:10px; }
.project-aow-agent-row > button { width:24px; height:24px; flex:0 0 24px; display:grid; place-items:center; padding:0; color:#a67873; border-radius:3px; }
.project-aow-agent-row > button:hover:not(:disabled) { color:#ef9f95; background:#422b29; }
.project-aow-agent-row > .project-aow-agent-edit { color:var(--aow-accent); }
.project-aow-agent-row > .project-aow-agent-edit:hover:not(:disabled),.project-aow-agent-row > .project-aow-agent-edit[aria-pressed="true"] { color:#c3dcfc; background:var(--aow-selection); }
@media(max-width:640px) {
  .project-aow-settings-body { grid-template-columns:minmax(0,1fr); grid-template-rows:auto minmax(0,1fr); }
  .project-aow-settings-nav { display:flex; gap:4px; padding:6px; border-right:0; border-bottom:1px solid var(--aow-line); }
  .project-aow-settings-nav button { width:auto; min-height:30px; flex:0 0 auto; padding:5px 8px; }
  .project-aow-settings-nav button small { display:none; }
  .project-aow-settings-nav button.active { box-shadow:inset 0 -2px var(--aow-accent); }
}
.confirmation-dialog { width:min(360px,calc(100vw - 24px)); max-height:calc(100dvh - 32px); margin:auto; padding:0; color:#d7dce3; border-radius:5px; box-shadow:0 8px 28px #000b; text-align:left; font-size:12px; }
.confirmation-dialog:not([open]) { display:none; }
.confirmation-dialog::backdrop { background:#0008; }
.confirmation-dialog > header { min-height:32px; padding:4px 6px 4px 12px; }
.confirmation-dialog h2 { flex:1; margin:0; color:#edf0f4; font-size:12px; font-weight:600; line-height:1.5; }
.confirmation-dialog > header > button { flex:0 0 22px; width:22px; height:22px; color:#919ba8; cursor:pointer; }
.confirmation-dialog > header > button svg { width:13px; height:13px; color:inherit; }
.confirmation-body { min-height:0; padding:10px 12px; overflow:auto; }
.confirmation-body > p { margin:0; color:#b1b9c5; line-height:1.5; overflow-wrap:anywhere; }
.confirmation-items { max-height:144px; margin:8px 0 0; padding:0; overflow:auto; list-style:none; background:#1b1f25; border:1px solid #383f49; border-radius:3px; }
.confirmation-items li { min-height:24px; display:flex; align-items:center; gap:6px; padding:4px 8px; }
.confirmation-items li + li { border-top:1px solid #303640; }
.confirmation-items li > svg { flex:0 0 14px; width:14px; height:14px; color:#80afe9; }
.confirmation-items li > .agent-icon { flex:0 0 14px; width:14px; height:14px; }
.confirmation-items li > div { min-width:0; display:flex; flex-direction:column; gap:1px; }
.confirmation-items strong { color:#dce2eb; font-size:11px; font-weight:500; line-height:16px; overflow-wrap:anywhere; }
.confirmation-items span { color:#8792a1; font:10px/1.4 ui-monospace,monospace; overflow-wrap:anywhere; }
.confirmation-warning { display:flex; align-items:flex-start; gap:6px; margin-top:8px; color:#c8a77d; }
.confirmation-warning > svg { flex:0 0 13px; width:13px; height:13px; margin-top:2px; color:#d4a46d; }
.confirmation-warning p { margin:0; font-size:11px; line-height:1.5; }
.confirmation-dialog > footer { flex:0 0 auto; gap:6px; margin:0; padding:7px 12px; background:#1e2228; border-top:1px solid #3b414b; }
.confirmation-dialog > footer button { min-height:24px; justify-content:center; padding:3px 9px; border-radius:3px; font-size:11px; line-height:16px; cursor:pointer; }
.confirmation-dialog > footer button.danger { color:#fff; background:#a6443e; border-color:#be554d; }
.confirmation-dialog > footer button.danger:hover { background:#ba4d45; border-color:#d2665c; }
.confirmation-dialog button:focus-visible { outline:1px solid #80afe9; outline-offset:2px; }

/// <reference types="vite/client" />

interface Window {
  MonacoEnvironment?: {
    getWorker(moduleId: string, label: string): Worker;
  };
  requestIdleCallback?(callback: () => void, options?: { timeout?: number }): number;
  cancelIdleCallback?(handle: number): void;
}
